window.VRAGEN_DATA=(window.VRAGEN_DATA||[]).concat([
 {id:'vbh-001',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-03T07:15:00',views:98,tags:['opstal','herbouwwaarde','onderverzekering'],beste:'vbh-001-a1',
  titel:'Herbouwwaarde opstal veel lager dan de WOZ-waarde: klopt dat?',
  body:`Bij een klant met een vrijstaande woning is de herbouwwaarde volgens de herbouwwaardemeter fors lager dan de WOZ-waarde. De klant denkt dat hij onderverzekerd is. Hoe leggen jullie dit verschil uit en wat leggen jullie vast?`,
  antwoorden:[
   {id:'vbh-001-a1',auteur:'u3',datum:'2025-10-04T03:12:00',rA:{u8:5,u2:4,u5:5},rAdv:{},body:`De WOZ-waarde is een marktwaarde inclusief grond en locatie, de herbouwwaarde gaat alleen over de kosten om de opstal opnieuw te bouwen. Een groot verschil is bij een vrijstaande woning op een duur perceel dus heel normaal. Ik loop met de klant de invoer van de herbouwwaardemeter door: inhoud, bouwaard, afwerking en bijgebouwen. Controleer daarnaast of de polis een garantie tegen onderverzekering kent en onder welke voorwaarden die geldt. In het dossier leg ik de berekening, de gebruikte uitgangspunten en de uitleg aan de klant vast.`},
   {id:'vbh-001-a2',auteur:'u5',datum:'2025-10-04T17:53:00',rA:{u2:5,u6:5,u1:5,u7:4},rAdv:{},body:`Aanvulling vanuit de hypotheekkant: de geldverstrekker vraagt meestal alleen dat de woning voor de volle herbouwwaarde is verzekerd, niet voor de WOZ- of marktwaarde. Controleer de voorwaarden van de geldverstrekker op dit punt. Ik neem de herbouwwaardeberekening mee in het hypotheekdossier, zodat later duidelijk is waarop de verzekerde som is gebaseerd.`}
  ]},
 {id:'vbh-002',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-06T13:15:00',views:152,tags:['inboedel','kostbaarheden','sieraden'],beste:'vbh-002-a1',
  titel:'Sieradenmaximum in de inboedelpolis te laag voor een klant',
  body:`Een klant heeft een sieradencollectie waarvan de waarde ruim boven het standaardmaximum in haar inboedelpolis ligt. Ze wil weten wat het verstandigst is. Kiezen jullie voor verhoging van het maximum of voor een aparte kostbaarhedenverzekering?`,
  antwoorden:[
   {id:'vbh-002-a1',auteur:'u3',datum:'2025-10-06T18:41:00',rA:{u5:5,u2:5},rAdv:{},body:`Dat hangt af van de waarde, het gebruik en de beveiligingseisen. Veel inboedelpolissen bieden een optionele verhoging van het maximum, maar daar horen vaak extra preventie-eisen bij, zoals een kluis of inbraakbeveiliging. Een aparte kostbaarhedenverzekering dekt vaak ook verlies en schade buitenshuis. Mijn checklist:
- taxatierapporten of aankoopnota's aanwezig?
- worden de sieraden ook buiten de deur gedragen?
- welke preventie-eisen stelt de verzekeraar?
Ik leg de afweging en de keuze van de klant vast in het dossier.`},
   {id:'vbh-002-a2',auteur:'u2',datum:'2025-10-07T10:32:00',rA:{u1:4,u3:3,u7:5,u8:5},rAdv:{},body:`Vanuit de financiële planning vraag ik ook of de collectie als belegging wordt gezien. Dan is het extra belangrijk dat taxaties periodiek worden geactualiseerd, anders klopt de verzekerde waarde na een paar jaar niet meer. Spreek een herinnering af in je klantcontactplan.`}
  ]},
 {id:'vbh-003',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-09T12:15:00',views:479,tags:['aansprakelijkheid','AVP','kinderen'],beste:null,
  titel:'Schade door kind van 12 bij vriendje thuis: welke AVP betaalt?',
  body:`Een kind van 12 heeft bij een vriendje thuis per ongeluk een televisie van de muur getrokken. De ouders van het vriendje willen de schade verhalen. Mijn klant vraagt of zijn AVP dit dekt. Hoe kijken jullie hiernaar?`,
  antwoorden:[
   {id:'vbh-003-a1',auteur:'u3',datum:'2025-10-10T04:29:00',rA:{u5:3,u8:4,u1:5,u4:4},rAdv:{u8:5,u4:5},body:`Voor kinderen jonger dan 14 jaar zijn de ouders op grond van artikel 6:169 BW in beginsel aansprakelijk als het gedrag van het kind als onrechtmatige daad zou gelden als het een volwassene was. De AVP van het gezin dekt die aansprakelijkheid in de regel. Controleer wel de uitsluitingen, vooral de opzichtclausule: was het kind bijvoorbeeld aan het spelen of had het de tv onder zich? Laat de klant de schade melden en neem geen aansprakelijkheid namens de verzekeraar op je. In het dossier noteer ik datum, toedracht en wat ik de klant heb geadviseerd.`},
   {id:'vbh-003-a2',auteur:'u8',datum:'2025-10-11T04:21:00',rA:{},rAdv:{},body:`Belangrijk punt vanuit compliance: geef geen toezegging over dekking voordat de verzekeraar heeft beoordeeld. Formuleer het als: op basis van de voorwaarden lijkt er dekking te zijn, de verzekeraar beslist. Zo voorkom je verwachtingen die je niet kunt waarmaken.`}
  ]},
 {id:'vbh-004',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-13T18:45:00',views:557,tags:['opstal','lekkage','eigen risico'],beste:'vbh-004-a1',
  titel:'Lekkage door slijtage van leiding: geen dekking volgens verzekeraar',
  body:`Een klant heeft waterschade door een lekkende leiding in de badkamer. De verzekeraar wijst de schade aan de leiding zelf af wegens slijtage, maar vergoedt wel de gevolgschade. De klant is boos. Hoe leggen jullie dit uit?`,
  antwoorden:[
   {id:'vbh-004-a1',auteur:'u3',datum:'2025-10-14T18:35:00',rA:{u7:5,u2:3,u8:5,u4:5},rAdv:{},body:`Dit is een veelvoorkomend onderscheid: de opstalverzekering dekt meestal de gevolgschade van plotseling uitstromend water, maar niet het herstel van het defecte onderdeel zelf als dat door slijtage komt. Vaak worden wel de kosten van opsporen en het openbreken en herstellen van vloeren of muren vergoed. Lees samen met de klant de betreffende clausule en laat zien wat wel en niet is gedekt. Leg in het dossier vast dat je dit hebt toegelicht en of de klant een klacht wil indienen.`}
  ]},
 {id:'vbh-005',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-17T13:40:00',views:425,tags:['storm','dakschade','preventie'],beste:null,
  titel:'Stormschade aan dak met oude dakpannen: kans op afwijzing?',
  body:`Een klant heeft stormschade aan een dak waarvan de pannen al tientallen jaren oud zijn. Hij vreest dat de verzekeraar zich beroept op achterstallig onderhoud. Hoe bereiden jullie zo een melding voor?`,
  antwoorden:[]},
 {id:'vbh-006',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-20T10:35:00',views:17,tags:['zorgplicht','schadeverzekering','periodieke check'],beste:'vbh-006-a2',
  titel:'Hoe vaak toetsen jullie lopende schadeverzekeringen opnieuw?',
  body:`Wij hebben veel klanten met een pakketpolis die al jaren niet zijn bekeken. Ik wil een vaste werkwijze om de passendheid periodiek te toetsen. Hoe richten jullie dat in en wat leggen jullie vast?`,
  antwoorden:[
   {id:'vbh-006-a1',auteur:'u8',datum:'2025-10-20T18:35:00',rA:{u3:5,u6:4,u1:5,u2:3},rAdv:{u7:3,u1:4,u3:3},body:`De wet schrijft geen vaste frequentie voor, maar je zorgplicht vraagt wel dat je klanten met een doorlopende dienstverlening niet uit het oog verliest. Wat ik in de praktijk zie werken:
- leg in je dienstverleningsdocument vast welke periodieke service je biedt;
- plan klantcontact op basis van risico, bijvoorbeeld bij grote levensgebeurtenissen;
- documenteer per contact welke wijzigingen zijn besproken.
Zorg vooral dat wat je belooft ook aantoonbaar gebeurt.`},
   {id:'vbh-006-a2',auteur:'u6',datum:'2025-10-21T05:46:00',rA:{},rAdv:{u8:3,u1:5},body:`In het CRM kun je hiervoor een terugkerende taak per relatie of per polis aanmaken, gekoppeld aan een vragenlijst voor de inventarisatie. Zo zie je in één overzicht welke klanten nog een check moeten krijgen en kun je de uitkomst direct in het dossier opslaan.`}
  ]},
 {id:'vbh-007',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-25T19:45:00',views:183,tags:['inboedel','verhuizing','dekking'],beste:null,
  titel:'Inboedel tijdens verhuizing: tijdelijk verzekerd op twee adressen?',
  body:`Een klant verhuist volgende maand en heeft een paar weken twee woningen. Een deel van de inboedel staat al in het nieuwe huis. Is de inboedel dan op beide adressen verzekerd?`,
  antwoorden:[
   {id:'vbh-007-a1',auteur:'u3',datum:'2025-10-26T07:22:00',rA:{u2:5},rAdv:{},body:`Veel inboedelpolissen bieden tijdens een verhuizing een periode waarin de inboedel op beide adressen is meeverzekerd, maar de duur en voorwaarden verschillen. Controleer ook of transport zelf is gedekt, vooral als de klant zelf verhuist met een huurbus. Laat de klant de adreswijziging tijdig doorgeven, want premie en acceptatie kunnen per postcode verschillen. Ik leg de nieuwe adresgegevens en de ingangsdatum van de wijziging vast.`},
   {id:'vbh-007-a2',auteur:'u1',datum:'2025-10-27T06:00:00',rA:{u6:3},rAdv:{u7:3,u6:3},body:`Bij mijn hypotheekklanten neem ik dit standaard mee in het afsluitgesprek: de opstal van de nieuwe woning moet vanaf het moment van eigendomsoverdracht geregeld zijn en de inboedel moet meeverhuizen. Een korte checklist in het dossier voorkomt dat dit erbij inschiet.`}
  ]},
 {id:'vbh-008',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-27T14:25:00',views:87,tags:['mededelingsplicht','acceptatie','strafrechtelijk verleden'],beste:'vbh-008-a1',
  titel:'Klant twijfelt of hij een oud strafrechtelijk verleden moet melden',
  body:`Bij het aanvragen van een nieuwe inboedel- en opstalverzekering vraagt de verzekeraar naar strafrechtelijk verleden. De klant heeft lang geleden een veroordeling gehad en twijfelt of hij dat moet melden. Hoe adviseren jullie?`,
  antwoorden:[
   {id:'vbh-008-a1',auteur:'u8',datum:'2025-10-27T18:54:00',rA:{},rAdv:{},body:`De mededelingsplicht van artikel 7:928 BW geldt voor feiten die de klant kent of behoort te kennen en waarvan het oordeel van de verzekeraar afhangt. Veel verzekeraars beperken de vraag naar strafrechtelijk verleden tot een bepaalde periode; lees de vraag in het aanvraagformulier dus letterlijk. Wijs de klant op de gevolgen van het niet of onjuist melden, maar vul de vraag nooit voor hem in. Leg vast dat je de mededelingsplicht hebt uitgelegd en dat de klant zelf heeft geantwoord.`},
   {id:'vbh-008-a2',auteur:'u3',datum:'2025-10-28T00:44:00',rA:{u1:5,u6:4,u4:4,u8:3},rAdv:{u1:3,u2:4,u7:4,u8:3},body:`Praktisch: neem bij twijfel vooraf contact op met de acceptatieafdeling, zonder direct naam en toenaam te geven. Dan weet de klant waar hij aan toe is voordat er een aanvraag ligt die mogelijk wordt geweigerd en ergens geregistreerd raakt.`}
  ]},
 {id:'vbh-009',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-30T14:05:00',views:540,tags:['opstal','zonnepanelen','dekking'],beste:'vbh-009-a1',
  titel:'Zonnepanelen op het dak: meeverzekerd onder de opstal?',
  body:`Een klant heeft zonnepanelen laten plaatsen. Hij gaat ervan uit dat die automatisch onder zijn opstalverzekering vallen. Wat controleren jullie en moet de herbouwwaarde worden aangepast?`,
  antwoorden:[
   {id:'vbh-009-a1',auteur:'u3',datum:'2025-10-31T07:24:00',rA:{u6:3},rAdv:{},body:`Bij veel verzekeraars vallen vast gemonteerde zonnepanelen onder de opstal, maar soms alleen als ze zijn gemeld of tot een bepaald maximum. Ik controleer:
- of zonnepanelen in de voorwaarden expliciet worden genoemd;
- of de herbouwwaarde moet worden verhoogd;
- of installatie door een erkend installateur een voorwaarde is.
Ik vraag de klant de factuur te bewaren en leg de wijziging en de aangepaste verzekerde som vast.`},
   {id:'vbh-009-a2',auteur:'u4',datum:'2025-10-31T09:28:00',rA:{u2:5},rAdv:{u2:5,u6:4,u1:4},body:`Huurt of least de klant de panelen? Dan is hij geen eigenaar en regelt de verhuurder vaak de verzekering. Check het contract, anders verzekert de klant iets wat niet van hem is.`}
  ]},
 {id:'vbh-010',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-04T20:15:00',views:552,tags:['aansprakelijkheid','huurder','opzicht'],beste:'vbh-010-a1',
  titel:'Huurder beschadigt keukenblad in huurwoning: AVP of opstal?',
  body:`Een huurder heeft met een hete pan het keukenblad van de huurwoning beschadigd. De verhuurder wil de schade verhalen. Valt dit onder de AVP van de huurder of onder een andere dekking?`,
  antwoorden:[
   {id:'vbh-010-a1',auteur:'u3',datum:'2025-11-05T00:05:00',rA:{u5:3,u8:4,u2:5},rAdv:{},body:`Schade aan de gehuurde woning valt bij veel AVP-polissen onder een uitsluiting of beperkte dekking, omdat de huurder de zaak onder zich heeft. Sommige inboedelpolissen hebben een huurdersbelangdekking voor verbeteringen die de huurder zelf heeft aangebracht, maar dat is iets anders dan schade aan het originele keukenblad. Lees de AVP-voorwaarden op de clausule over gehuurde woningen na; sommige verzekeraars dekken schade aan het gehuurde huis wel, met uitzonderingen. Leg vast wat je de klant hebt verteld en dat de verzekeraar uiteindelijk beslist.`}
  ]},
 {id:'vbh-011',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-07T07:30:00',views:186,tags:['schadebehandeling','expert','contra-expertise'],beste:'vbh-011-a3',
  titel:'Wanneer adviseren jullie een eigen contra-expert?',
  body:`Bij een grote brandschade is de expert van de verzekeraar met een vaststelling gekomen die de klant te laag vindt. De klant vraagt of hij een eigen expert moet inschakelen. Wanneer raden jullie dat aan en wie betaalt?`,
  antwoorden:[
   {id:'vbh-011-a1',auteur:'u3',datum:'2025-11-08T07:01:00',rA:{u5:5,u7:4,u8:3},rAdv:{u8:4,u7:5},body:`Veel polissen vergoeden de kosten van een eigen expert tot maximaal de kosten van de expert van de verzekeraar, maar controleer dit in de voorwaarden. Bij een grote of complexe schade adviseer ik het vrijwel altijd, zeker als de herstelmethode of de herbouwwaarde ter discussie staat. Laat de klant niets afstemmen of ondertekenen voordat de eigen expert betrokken is. In het dossier noteer ik het advies, de reden en de afspraken over kosten.`},
   {id:'vbh-011-a2',auteur:'u8',datum:'2025-11-08T11:52:00',rA:{u2:4,u1:5},rAdv:{},body:`Let erop dat je als adviseur geen belang hebt bij de keuze van de expert, of maak dat belang transparant. Leg ook vast dat de klant zelf heeft gekozen.`},
   {id:'vbh-011-a3',auteur:'u2',datum:'2025-11-09T05:07:00',rA:{u6:3},rAdv:{},body:`Bij grote schades kijk ik ook naar de liquiditeit van de klant: kan hij het herstel voorfinancieren als de afwikkeling lang duurt? Vraag tijdig een voorschot aan bij de verzekeraar.`}
  ]},
 {id:'vbh-012',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-10T09:30:00',views:218,tags:['glasschade','opstal','huurder'],beste:null,
  titel:'Glasschade bij een huurwoning: wie moet het verzekeren?',
  body:`Een huurder heeft een gebroken ruit en vraagt of zijn eigen inboedelpolis dit dekt. Hij heeft geen aparte glasverzekering. Hoe zit dit doorgaans in elkaar?`,
  antwoorden:[
   {id:'vbh-012-a1',auteur:'u3',datum:'2025-11-11T07:10:00',rA:{},rAdv:{u6:5,u8:3,u2:4},body:`Glas maakt deel uit van de opstal en is dus primair een zaak van de eigenaar. In het huurcontract staat vaak wie verantwoordelijk is voor glasschade; soms moet de huurder dat zelf regelen of betaalt hij een vergoeding voor een glasfonds. Sommige inboedelpolissen bevatten een beperkte huurdersdekking voor glas. Laat de klant eerst het huurcontract erbij pakken en leg vast wat daarin staat.`}
  ]},
 {id:'vbh-013',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-16T19:20:00',views:193,tags:['inboedel','fiets','e-bike'],beste:'vbh-013-a1',
  titel:'E-bike gestolen uit schuur: inboedel of aparte fietsverzekering?',
  body:`Een klant had een dure e-bike in een afgesloten schuur staan en deze is gestolen. De inboedelverzekering lijkt een maximum te hebben voor fietsen buiten de woning. Hoe pakken jullie dit aan?`,
  antwoorden:[
   {id:'vbh-013-a1',auteur:'u3',datum:'2025-11-17T15:43:00',rA:{u1:3,u5:4,u8:3,u7:5},rAdv:{u5:3,u7:4,u4:4,u1:5},body:`Inboedelpolissen dekken diefstal van fietsen vaak alleen uit een afgesloten ruimte bij de woning en dan met een maximum per fiets. Controleer of er braaksporen zijn, want zonder braak volgt vaak afwijzing. Voor een dure e-bike adviseer ik vooraf meestal een aparte fietsverzekering met dagwaarde- of nieuwwaarderegeling. Nu de schade er is: melden, aangifte doen en aankoopnota aanleveren. In het dossier zet ik dat ik het maximum met de klant heb besproken.`},
   {id:'vbh-013-a2',auteur:'u2',datum:'2025-11-17T22:13:00',rA:{u4:3,u8:5,u3:3},rAdv:{u1:5,u5:5,u7:3},body:`Goede tip voor de periodieke check: vraag actief naar dure aankopen sinds het laatste contact, zoals e-bikes en elektronica. Dat zijn precies de posten die vaak boven de maxima uitkomen.`}
  ]},
 {id:'vbh-014',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-18T10:20:00',views:40,tags:['opstal','leegstand','acceptatie'],beste:null,
  titel:'Woning staat maanden leeg na overlijden: blijft opstal geldig?',
  body:`De erfgenamen van een overleden klant laten de woning leeg staan totdat deze is verkocht. Ik weet dat leegstand gevolgen kan hebben voor de dekking. Wat moeten zij regelen?`,
  antwoorden:[]},
 {id:'vbh-015',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-21T11:35:00',views:541,tags:['schadebehandeling','Kifid','klacht'],beste:'vbh-015-a1',
  titel:'Klant wil naar het Kifid na afwijzing inboedelschade',
  body:`De verzekeraar heeft een inboedelschade afgewezen en ook de interne klachtprocedure heeft niets opgeleverd. De klant wil naar het Kifid. Hoe begeleiden jullie dit als adviseur?`,
  antwoorden:[
   {id:'vbh-015-a1',auteur:'u8',datum:'2025-11-22T02:17:00',rA:{u4:5,u5:4},rAdv:{u7:4,u1:4,u5:4,u6:5},body:`Eerst moet de interne klachtprocedure bij de verzekeraar zijn doorlopen; daarna kan de klant binnen de geldende termijn naar het Kifid. Wijs de klant op die termijn en help hem het dossier compleet te maken: polis, voorwaarden, correspondentie en de afwijzingsbrief. Je kunt de klant ondersteunen, maar laat hem zelf de klacht indienen of leg een machtiging vast. Noteer in het dossier welke hulp je hebt geboden en welke stukken zijn verstrekt.`},
   {id:'vbh-015-a2',auteur:'u3',datum:'2025-11-22T14:33:00',rA:{u7:3},rAdv:{u6:4},body:`Praktisch: maak een korte tijdlijn van de schade en alle contacten. Dat helpt het Kifid enorm en voorkomt dat er onduidelijkheid ontstaat over wat wanneer is gezegd.`}
  ]},
 {id:'vbh-016',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-25T13:40:00',views:362,tags:['aansprakelijkheid','hond','dieren'],beste:null,
  titel:'Hond bijt bezoeker: aansprakelijk ook zonder schuld?',
  body:`De hond van een klant heeft een bezoeker gebeten. De klant zegt dat de bezoeker de hond had uitgedaagd. Is de klant dan toch aansprakelijk en dekt de AVP dit?`,
  antwoorden:[
   {id:'vbh-016-a1',auteur:'u3',datum:'2025-11-26T09:47:00',rA:{u7:5},rAdv:{},body:`Op grond van artikel 6:179 BW is de bezitter van een dier risicoaansprakelijk voor schade die het dier aanricht. Eigen schuld van het slachtoffer kan wel tot een vermindering van de vergoeding leiden, maar dat beoordeelt de verzekeraar. De AVP dekt dit doorgaans; controleer wel of er uitsluitingen gelden voor bepaalde rassen of voor bedrijfsmatig gehouden dieren. Laat de klant snel melden en geen schuld erkennen.`},
   {id:'vbh-016-a2',auteur:'u8',datum:'2025-11-26T22:40:00',rA:{u1:4,u4:5,u5:5},rAdv:{u5:4},body:`Leg in je dossier vast dat je de klant hebt gewezen op het niet zelf erkennen van aansprakelijkheid. Dat staat vaak ook als verplichting in de polisvoorwaarden.`}
  ]},
 {id:'vbh-017',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-29T17:30:00',views:200,tags:['opstal','verbouwing','melding'],beste:'vbh-017-a3',
  titel:'Verbouwing tijdens looptijd: wat moet de klant melden?',
  body:`Een klant gaat zijn woning flink verbouwen en uitbreiden met een aanbouw. Wat moet hij melden aan de opstalverzekeraar en wanneer?`,
  antwoorden:[
   {id:'vbh-017-a1',auteur:'u3',datum:'2025-11-29T21:42:00',rA:{u4:4,u1:4},rAdv:{},body:`Bij een verbouwing verandert vaak het risico en de herbouwwaarde. Ik adviseer de klant om vooraf te melden: tijdens de bouw kunnen beperkingen gelden, bijvoorbeeld voor diefstal van bouwmaterialen of bij een tijdelijk onbewoonbare woning. Na oplevering wordt de herbouwwaarde opnieuw berekend. Controleer ook of de aannemer een CAR-verzekering heeft. Ik leg de meldingsdatum en de nieuwe herbouwwaarde vast.`},
   {id:'vbh-017-a2',auteur:'u4',datum:'2025-11-29T23:01:00',rA:{u8:5,u5:5},rAdv:{u6:5,u3:5,u7:5},body:`Als de verbouwing gefinancierd wordt met een bouwdepot, vraagt de geldverstrekker vaak ook om een aangepaste opstalpolis na oplevering. Controleer de voorwaarden van de geldverstrekker en plan dat in je dossier.`},
   {id:'vbh-017-a3',auteur:'u5',datum:'2025-11-30T15:53:00',rA:{},rAdv:{},body:`Goede aanvulling: ik plan bij bouwdepots standaard een vervolgcontact na de geplande opleverdatum, zodat de nieuwe herbouwwaarde niet vergeten wordt.`}
  ]},
 {id:'vbh-018',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-02T19:30:00',views:107,tags:['inboedel','onderverzekering','inboedelwaardemeter'],beste:'vbh-018-a1',
  titel:'Inboedelwaardemeter of vaste som: wat adviseren jullie?',
  body:`Een klant wil de inboedel liever voor een vast bedrag verzekeren in plaats van via de inboedelwaardemeter. Hij denkt zo premie te besparen. Wat zijn de risico's?`,
  antwoorden:[
   {id:'vbh-018-a1',auteur:'u3',datum:'2025-12-03T04:01:00',rA:{u4:3,u2:3,u7:5,u5:5},rAdv:{},body:`Met een vaste som loopt de klant het risico op onderverzekering, waardoor bij een schade naar verhouding wordt uitgekeerd. Via de inboedelwaardemeter geldt vaak een garantie tegen onderverzekering, mits de gegevens juist zijn ingevuld. Ik laat beide varianten zien en bespreek wat er bij een grote schade gebeurt. Kiest de klant toch voor een vaste som, dan leg ik dat besluit en de toelichting vast.`}
  ]},
 {id:'vbh-019',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-05T10:05:00',views:251,tags:['zorgplicht','IDD','wensen en behoeften'],beste:null,
  titel:'Wat leggen jullie vast voor de wensen- en behoeftentoets bij schade?',
  body:`Onder IDD moet je bij schadeverzekeringen de wensen en behoeften van de klant in kaart brengen. Hoe uitgebreid doen jullie dat bij een eenvoudig pakket van inboedel, opstal en AVP?`,
  antwoorden:[
   {id:'vbh-019-a1',auteur:'u8',datum:'2025-12-06T02:19:00',rA:{u5:4,u6:4,u2:4,u3:4},rAdv:{},body:`Ook bij eenvoudige producten moet je kunnen aantonen dat het product past bij de wensen en behoeften. Dat hoeft niet zwaar te zijn: een korte inventarisatie van woonsituatie, gezinssituatie, waardevolle bezittingen en risicobereidheid is vaak voldoende. Leg vast welke opties je hebt besproken, zoals eigen risico en aanvullende dekkingen. Verstrek het productinformatiedocument en leg vast dat je dat hebt gedaan.`},
   {id:'vbh-019-a2',auteur:'u6',datum:'2025-12-07T01:35:00',rA:{u4:3,u1:4},rAdv:{u7:3,u4:4,u1:3},body:`In het adviespakket kun je een standaard vragenlijst voor particuliere schade gebruiken die automatisch in het dossier wordt opgeslagen. Dat bespaart tijd en zorgt voor een uniforme vastlegging.`}
  ]},
 {id:'vbh-020',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-09T14:30:00',views:188,tags:['opstal','aardbeving','uitsluiting'],beste:'vbh-020-a1',
  titel:'Is aardbevingsschade gedekt onder de standaard opstalpolis?',
  body:`Een klant in het noorden van het land vraagt of aardbevingsschade onder zijn opstal valt. Ik weet dat dit vaak is uitgesloten. Hoe adviseren jullie hierover?`,
  antwoorden:[
   {id:'vbh-020-a1',auteur:'u3',datum:'2025-12-10T01:35:00',rA:{u6:4},rAdv:{u6:3,u4:4,u7:3,u5:3},body:`Aardbeving staat in veel opstalvoorwaarden als uitsluiting of beperkt gedekt. Voor schade door gaswinning is er in het betreffende gebied een aparte publieke regeling. Lees de clausule precies na en verwijs de klant voor mijnbouwschade naar de daarvoor bestemde instantie. Leg vast dat je de beperking hebt besproken.`},
   {id:'vbh-020-a2',auteur:'u7',datum:'2025-12-10T23:14:00',rA:{u2:5,u4:3,u5:3},rAdv:{u5:3,u1:4,u4:4},body:`Mijn kantoor zit in die regio: klanten vinden het prettig als je ook de procedure voor schademelding bij de publieke regeling kort uitlegt. Verwijs naar de actuele informatie van die instantie, want de regeling wordt regelmatig aangepast.`}
  ]},
 {id:'vbh-021',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-14T09:45:00',views:256,tags:['aansprakelijkheid','drone','uitsluiting'],beste:'vbh-021-a1',
  titel:'Drone van klant veroorzaakt schade: valt dat onder de AVP?',
  body:`Een klant vliegt recreatief met een drone en vraagt of schade aan derden onder zijn AVP valt. In de voorwaarden staat iets over luchtvaartuigen. Hoe interpreteren jullie dit?`,
  antwoorden:[
   {id:'vbh-021-a1',auteur:'u3',datum:'2025-12-14T19:21:00',rA:{u5:4,u6:3,u8:3,u7:4},rAdv:{u8:3,u7:4,u6:5},body:`Veel AVP-polissen sluiten luchtvaartuigen uit, maar maken een uitzondering voor kleine modelvliegtuigen of drones onder een bepaald gewicht. Controleer de exacte formulering en het gewicht van de drone. Wijs de klant ook op de regels voor recreatief vliegen, want schade bij het overtreden van wettelijke regels kan tot discussie leiden. Leg vast welke dronetype en welk gewicht je hebt besproken.`}
  ]},
 {id:'vbh-022',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-16T16:25:00',views:93,tags:['opstal','zwembad','tuin'],beste:null,
  titel:'Zwembad en tuinaanleg: meeverzekerd onder opstal?',
  body:`Een klant heeft een ingegraven zwembad laten aanleggen en een dure tuin. Hij vraagt of dit onder zijn opstalverzekering valt. Wat zien jullie in de praktijk?`,
  antwoorden:[]},
 {id:'vbh-023',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-21T14:35:00',views:133,tags:['schadebehandeling','bereddingskosten','waterschade'],beste:null,
  titel:'Worden kosten van het beperken van schade vergoed?',
  body:`Bij een lekkage heeft een klant direct een loodgieter met spoedtoeslag laten komen en bouwdrogers gehuurd. Worden deze kosten vergoed?`,
  antwoorden:[
   {id:'vbh-023-a1',auteur:'u3',datum:'2025-12-22T05:59:00',rA:{u1:4,u7:4},rAdv:{},body:`Kosten die de klant maakt om dreigende schade te voorkomen of te beperken heten bereddingskosten en worden op grond van artikel 7:957 BW vergoed, ook boven de verzekerde som. Voorwaarde is wel dat de schade zelf onder de dekking valt. Laat de klant facturen en foto's bewaren en direct melden. In het dossier zet ik welke kosten zijn gemaakt en dat ik de klant heb geadviseerd ze in te dienen.`},
   {id:'vbh-023-a2',auteur:'u8',datum:'2025-12-22T19:31:00',rA:{u4:5,u3:4,u1:4},rAdv:{},body:`Wijs de klant er ook op dat hij redelijke maatregelen moet nemen. Onnodig dure keuzes kunnen ter discussie staan, maar acute spoedkosten zijn meestal redelijk.`}
  ]},
 {id:'vbh-024',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-25T14:30:00',views:335,tags:['inboedel','studerende kinderen','dekking'],beste:'vbh-024-a1',
  titel:'Inboedel van uitwonend studerend kind: meeverzekerd bij ouders?',
  body:`Een klant heeft een dochter die op kamers woont. Haar laptop en fiets zijn gestolen uit haar studentenkamer. Valt dit onder de inboedelpolis van de ouders?`,
  antwoorden:[
   {id:'vbh-024-a1',auteur:'u3',datum:'2025-12-26T09:14:00',rA:{},rAdv:{u8:5,u7:4},body:`Veel inboedelpolissen dekken de spullen van uitwonende studerende kinderen tot een bepaald maximum en vaak alleen bij braak. Controleer de definitie van gezinsleden en de voorwaarden voor buitenshuis. De fiets valt vaak onder aparte maxima. Wijs de klant erop dat de kamer zelf meestal niet is verzekerd en dat de dochter mogelijk ook een eigen AVP nodig heeft als ze niet meer onder de gezinspolis valt.`},
   {id:'vbh-024-a2',auteur:'u2',datum:'2025-12-26T23:29:00',rA:{},rAdv:{},body:`Goede vraag om standaard te stellen als kinderen uit huis gaan: blijft de dochter onder de AVP en zorgverzekering van het gezin vallen, en wat als ze gaat samenwonen? Dit levert vaak een wijziging op die meerdere polissen raakt.`}
  ]},
 {id:'vbh-025',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-27T07:15:00',views:357,tags:['aansprakelijkheid','vrijwilligerswerk','AVP'],beste:'vbh-025-a1',
  titel:'Schade bij vrijwilligerswerk: AVP of verzekering van vereniging?',
  body:`Een klant doet vrijwilligerswerk bij de sportclub en heeft daarbij schade veroorzaakt aan materiaal van een derde. Welke verzekering is hier primair?`,
  antwoorden:[
   {id:'vbh-025-a1',auteur:'u3',datum:'2025-12-27T16:04:00',rA:{u5:5},rAdv:{u2:4,u7:5},body:`Bij vrijwilligerswerk is vaak eerst de aansprakelijkheidsverzekering van de vereniging of de gemeentelijke vrijwilligersverzekering aan de beurt. De AVP van de vrijwilliger kan secundair dekken, afhankelijk van de voorwaarden en de samenloopclausule. Laat de klant bij de vereniging navragen welke verzekeringen zij heeft. Leg vast dat je de mogelijke samenloop hebt besproken.`}
  ]},
 {id:'vbh-026',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-29T07:35:00',views:277,tags:['opstal','neerslag','onderhoud'],beste:'vbh-026-a1',
  titel:'Lekkage via plat dak na hevige regen: neerslag of slecht onderhoud?',
  body:`Bij een klant is na een flinke regenbui water via het platte dak de woonkamer in gelopen. De verzekeraar wijst af omdat de dakbedekking verouderd zou zijn. De klant vindt dat het om plotselinge neerslag gaat. Hoe sterk staat hij?`,
  antwoorden:[
   {id:'vbh-026-a1',auteur:'u3',datum:'2025-12-29T21:49:00',rA:{u4:5,u2:5,u6:5},rAdv:{u8:5},body:`Veel polissen dekken schade door neerslag die onvoorzien de woning binnenkomt, maar sluiten schade door slecht onderhoud uit. De verzekeraar moet het beroep op de uitsluiting wel onderbouwen, meestal met een expertiserapport. Vraag dat rapport op en laat de klant onderhoudsfacturen of foto's van eerdere inspecties aanleveren. Controleer ook of de polis een aparte regeling heeft voor platte daken. In het dossier leg ik vast welke stukken we hebben aangeleverd en wat de reactie van de verzekeraar was.`},
   {id:'vbh-026-a2',auteur:'u8',datum:'2025-12-30T16:44:00',rA:{},rAdv:{},body:`Let erop dat je als adviseur de klant ondersteunt, maar geen toezeggingen doet over de uitkomst. Benoem ook de route via de interne klachtenprocedure van de verzekeraar als de afwijzing blijft staan.`}
  ]},
 {id:'vbh-027',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-02T14:50:00',views:365,tags:['inboedel','onderverzekering','zorgplicht'],beste:'vbh-027-a2',
  titel:'Onderverzekering inboedel blijkt pas bij schade: wat nu?',
  body:`Na een inbraak blijkt het verzekerd bedrag van de inboedel duidelijk te laag. De verzekeraar past onderverzekering toe en keert naar verhouding uit. De klant vraagt of wij dit hadden moeten signaleren. Hoe gaan jullie hiermee om?`,
  antwoorden:[
   {id:'vbh-027-a1',auteur:'u8',datum:'2026-01-03T01:53:00',rA:{u2:4,u6:4},rAdv:{},body:`Kijk eerst in het dossier: is de inboedelwaarde ooit met de klant besproken en heeft de klant een vaste som gekozen in plaats van een waardemeter? Als je periodiek hebt gewezen op het actualiseren van de waarde en dat is vastgelegd, sta je sterker. Is dat niet gebeurd, meld het dan intern en overweeg of je beroepsaansprakelijkheidsverzekeraar geïnformeerd moet worden. Wees in je communicatie naar de klant feitelijk en neem geen aansprakelijkheid op je voordat je het dossier hebt beoordeeld.`},
   {id:'vbh-027-a2',auteur:'u3',datum:'2026-01-03T03:15:00',rA:{u7:4,u8:5,u6:4,u5:5},rAdv:{u2:4},body:`Controleer ook of de polis een garantie tegen onderverzekering kent bij gebruik van een waardemeter. Soms is die er en is de waardemeter wel ooit ingevuld; dan kan de verzekeraar alsnog volledig uitkeren.`},
   {id:'vbh-027-a3',auteur:'u2',datum:'2026-01-03T17:07:00',rA:{u3:5},rAdv:{u4:4,u5:4,u8:5},body:`Neem het voorval mee als aanleiding om bij alle klanten met een vaste som de inboedelwaarde opnieuw op te vragen.`}
  ]},
 {id:'vbh-028',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-05T09:35:00',views:195,tags:['opzegging','schadefrequentie','woonverzekering'],beste:'vbh-028-a1',
  titel:'Verzekeraar zegt woonpolis op na drie schades in twee jaar',
  body:`Een klant heeft in korte tijd drie schades geclaimd en de verzekeraar zegt nu de woonverzekering op. De klant vreest dat hij nergens anders meer terecht kan. Hoe pakken jullie dit aan?`,
  antwoorden:[
   {id:'vbh-028-a1',auteur:'u3',datum:'2026-01-05T13:21:00',rA:{u5:5,u4:5,u7:4},rAdv:{u1:5,u4:5},body:`Controleer eerst of de opzegging volgens de voorwaarden is gedaan, met de juiste termijn. Bij een nieuwe aanvraag moet de klant de opzegging en de schades melden op de slotvragen; verzwijgen kan later tot problemen leiden. In de praktijk lukt het vaak wel om elders onder te brengen, soms met een hogere premie of eigen risico. Bespreek ook of preventieve maatregelen het risico verlagen. Leg vast welke verzekeraars je hebt benaderd en met welke uitkomst.`},
   {id:'vbh-028-a2',auteur:'u8',datum:'2026-01-06T04:53:00',rA:{u7:5,u1:3,u6:4},rAdv:{u4:5},body:`Zorg dat de klant niet onverzekerd raakt. Plan de nieuwe aanvraag ruim voor de einddatum en controleer bij een hypotheek of er een verplichting tot opstalverzekering is.`}
  ]},
 {id:'vbh-029',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-09T17:05:00',views:48,tags:['fraude','registratie','schadebehandeling'],beste:'vbh-029-a1',
  titel:'Registratie in incidentenregister na schademelding: wat kan de klant doen?',
  body:`Een klant is na een schademelding geregistreerd in het interne incidentenregister van de verzekeraar en mogelijk ook extern. Hij ontkent fraude. Wat kunnen wij als adviseur voor hem doen?`,
  antwoorden:[
   {id:'vbh-029-a1',auteur:'u8',datum:'2026-01-09T20:02:00',rA:{u6:4,u5:3,u3:4,u7:4},rAdv:{u6:3},body:`De klant heeft op grond van de AVG recht op inzage in de gegevens die over hem zijn vastgelegd. Laat hem een inzageverzoek doen bij de verzekeraar en eventueel bij de externe registratie. Is hij het oneens, dan kan hij bezwaar maken en een klacht indienen via de interne klachtenprocedure en daarna bij het Kifid. Als adviseur kun je helpen met het verzamelen van stukken, maar wees terughoudend in je eigen oordeel over de feiten.`},
   {id:'vbh-029-a2',auteur:'u3',datum:'2026-01-10T00:31:00',rA:{},rAdv:{u6:4},body:`Houd er rekening mee dat een registratie gevolgen kan hebben voor nieuwe aanvragen. Vraag na hoe lang de registratie duurt volgens het geldende protocol en leg in het dossier vast wat je met de klant hebt besproken.`}
  ]},
 {id:'vbh-030',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-13T16:55:00',views:64,tags:['vakantieverhuur','opstal','inboedel'],beste:null,
  titel:'Woning verhuren aan toeristen: blijft de woonverzekering geldig?',
  body:`Een klant wil zijn woning een paar weken per jaar verhuren via een verhuurplatform. Hij vraagt of zijn opstal- en inboedelverzekering dan nog geldig zijn. Wat checken jullie?`,
  antwoorden:[
   {id:'vbh-030-a1',auteur:'u3',datum:'2026-01-14T02:41:00',rA:{u7:4,u8:4},rAdv:{u5:4},body:`Veel woonpolissen gaan uit van eigen bewoning en sluiten schade tijdens verhuur geheel of gedeeltelijk uit, zeker bij diefstal zonder braak. Controleer de voorwaarden op bepalingen over verhuur en gebruik door derden en meld de verhuur vooraf bij de verzekeraar. Soms is er een aanvullende dekking mogelijk, soms biedt het platform een eigen regeling met beperkingen. Vergeet de AVP niet: aansprakelijkheid als verhuurder kan buiten de particuliere dekking vallen.`},
   {id:'vbh-030-a2',auteur:'u5',datum:'2026-01-14T12:45:00',rA:{},rAdv:{u4:4},body:`Wijs de klant ook op de hypotheekvoorwaarden en eventuele regels van de gemeente of de VvE. Verhuur zonder toestemming kan daar problemen geven, los van de verzekering.`}
  ]},
 {id:'vbh-031',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-16T08:35:00',views:423,tags:['kamerverhuur','inboedel','AVP'],beste:null,
  titel:'Kamer verhuren aan een student: wat betekent dat voor de verzekeringen?',
  body:`Een klant gaat een kamer in haar woning verhuren aan een student. Moet ze dit melden bij de woonverzekering en is de inboedel van de student meeverzekerd?`,
  antwoorden:[]},
 {id:'vbh-032',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-20T18:15:00',views:513,tags:['inboedel','thuiswerken','zakelijk'],beste:'vbh-032-a1',
  titel:'Thuiswerkplek: is zakelijke apparatuur meeverzekerd onder de inboedel?',
  body:`Een klant werkt grotendeels thuis en heeft een laptop en scherm van zijn werkgever. Daarnaast heeft hij als zzp'er eigen apparatuur. Wat valt hiervan onder de particuliere inboedelpolis?`,
  antwoorden:[
   {id:'vbh-032-a1',auteur:'u3',datum:'2026-01-20T21:14:00',rA:{u1:4},rAdv:{u1:5},body:`Spullen van de werkgever vallen meestal niet onder de inboedel van de werknemer; daarvoor is doorgaans de werkgever verzekerd. Bij eigen zakelijke apparatuur van een zzp'er verschilt het per polis: sommige dekken een beperkt bedrag aan bedrijfsuitrusting, andere sluiten het uit. Controleer de definitie van inboedel en eventuele maxima voor beroepsuitrusting. Bij grotere waarden adviseer ik een aparte zakelijke inventarisverzekering.`},
   {id:'vbh-032-a2',auteur:'u2',datum:'2026-01-21T08:08:00',rA:{u5:4},rAdv:{u5:4,u4:4},body:`Neem dit mee in de inventarisatie bij zzp'ers. Thuiswerkers onderschatten vaak wat er aan zakelijke spullen in huis staat.`}
  ]},
 {id:'vbh-033',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-24T18:00:00',views:188,tags:['brand','grove schuld','inboedel'],beste:'vbh-033-a1',
  titel:'Brand door brandende kaarsen: kan de verzekeraar grove schuld tegenwerpen?',
  body:`Een klant is weggegaan terwijl er kaarsen brandden, met brandschade als gevolg. De verzekeraar overweegt een beroep op grove schuld. Hoe kijken jullie hiernaar?`,
  antwoorden:[
   {id:'vbh-033-a1',auteur:'u3',datum:'2026-01-25T07:13:00',rA:{u6:5},rAdv:{u7:4},body:`Bij brand ligt de lat voor grove schuld in de praktijk vaak hoog; veel polissen dekken brand ook bij eigen schuld. Controleer of de voorwaarden een specifieke bepaling hebben over roekeloosheid of opzet en lees hoe de verzekeraar dit onderbouwt. De omstandigheden tellen mee: hoe lang was de klant weg en waar stonden de kaarsen? Vraag om een schriftelijke motivering en leg de verklaring van de klant zorgvuldig vast.`},
   {id:'vbh-033-a2',auteur:'u8',datum:'2026-01-26T03:42:00',rA:{u1:4,u4:5},rAdv:{u2:5,u3:4,u4:4},body:`Laat de klant zijn verklaring zelf opstellen en controleren. Als adviseur vul je die niet aan met eigen interpretaties. Bij twijfel is de klachtenroute een optie.`}
  ]},
 {id:'vbh-034',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-28T10:50:00',views:376,tags:['inbraak','braaksporen','inboedel'],beste:null,
  titel:'Inbraak zonder braaksporen: verzekeraar keert niet uit',
  body:`Bij een klant zijn spullen verdwenen uit de woning, maar er zijn geen braaksporen. De verzekeraar wijst af. De klant vermoedt dat er een reservesleutel is misbruikt. Hebben jullie dit eerder gezien?`,
  antwoorden:[
   {id:'vbh-034-a1',auteur:'u3',datum:'2026-01-29T06:00:00',rA:{u5:4},rAdv:{u5:3},body:`Veel polissen eisen voor diefstal uit de woning sporen van braak, zeker voor bepaalde categorieën spullen. Sommige polissen kennen een ruimere dekking of een uitzondering als de dief binnenkwam zonder braak, bijvoorbeeld via een open raam, met een eigen maximum. Lees de voorwaarden goed na en laat de klant aangifte doen als dat nog niet is gebeurd. Is er een concrete aanwijzing voor misbruik van een sleutel, vraag dan of de verzekeraar dat wil meewegen.`},
   {id:'vbh-034-a2',auteur:'u4',datum:'2026-01-29T23:02:00',rA:{u8:4,u6:5,u5:5,u7:5},rAdv:{u1:4,u3:4,u2:4,u8:4},body:`Bespreek bij nieuwe klanten gelijk of de woonpolis een all-riskdekking heeft. Bij een uitgebreide dekking zonder all-risk is diefstal zonder braak vaak niet of beperkt gedekt.`}
  ]},
 {id:'vbh-035',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-31T08:30:00',views:481,tags:['diefstal','buitenshuis','reisverzekering'],beste:'vbh-035-a1',
  titel:'Spullen gestolen uit geparkeerde auto: inboedel of reisverzekering?',
  body:`Uit de auto van een klant is in Nederland een tas met laptop gestolen. De auto was afgesloten. Kan dit onder de inboedelverzekering vallen, of moet dat via een andere polis?`,
  antwoorden:[
   {id:'vbh-035-a1',auteur:'u3',datum:'2026-01-31T10:17:00',rA:{u6:4,u4:5,u2:4,u1:5},rAdv:{},body:`Dekking buitenshuis is bij inboedelpolissen beperkt en verschilt sterk. Sommige polissen dekken diefstal uit een afgesloten auto met braaksporen, vaak met een laag maximum en soms alleen als de spullen niet zichtbaar lagen. Een doorlopende reisverzekering dekt meestal alleen tijdens een reis met een bepaald minimum. Controleer beide polissen en de eventuele all-riskmodule voor mobiele apparatuur. Leg de uitkomst vast zodat je bij een volgende review de dekking voor buitenshuis kunt bespreken.`}
  ]},
 {id:'vbh-036',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-04T18:30:00',views:9,tags:['reisverzekering','samenloop','telefoon'],beste:'vbh-036-a1',
  titel:'Vakantie in het buitenland: telefoon gestolen, welke polis?',
  body:`Een klant heeft zowel een doorlopende reisverzekering als een inboedelpolis met buitenhuisdekking. Op vakantie is zijn telefoon gestolen. Bij welke verzekeraar meldt hij dit?`,
  antwoorden:[
   {id:'vbh-036-a1',auteur:'u3',datum:'2026-02-05T16:01:00',rA:{u4:5},rAdv:{u8:3},body:`Bij twee polissen die hetzelfde risico dekken bepalen de samenloopbepalingen wie betaalt. Vaak verwijzen beide naar elkaar en delen ze de schade, of gaat de reisverzekering voor. Laat de klant bij één verzekeraar melden en vermelden dat er een tweede polis is. Let op de eisen: aangifte bij de lokale politie binnen korte tijd en bewijs van aankoop. Controleer ook het maximum voor telefoons, dat is bij reisverzekeringen vaak beperkt.`},
   {id:'vbh-036-a2',auteur:'u2',datum:'2026-02-05T21:21:00',rA:{u7:4,u4:4,u3:4,u1:4},rAdv:{u1:3,u4:4},body:`Goed moment om te kijken of de klant geen dubbele dekkingen betaalt. Soms is een buitenhuisdekking op de inboedel overbodig naast een uitgebreide reisverzekering, of juist andersom.`}
  ]},
 {id:'vbh-037',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-08T07:25:00',views:198,tags:['opstal','fundering','verzakking'],beste:'vbh-037-a1',
  titel:'Scheuren in muren door verzakking: valt dat onder de opstal?',
  body:`Een klant heeft scheuren in de gevel en binnenmuren. Een bouwkundige wijst op funderingsproblemen. De klant hoopt op dekking via de opstalverzekering. Wat is jullie ervaring?`,
  antwoorden:[
   {id:'vbh-037-a1',auteur:'u3',datum:'2026-02-08T20:31:00',rA:{u4:4},rAdv:{u1:3},body:`Schade door verzakking, zetting of funderingsproblemen is bij de meeste opstalpolissen uitgesloten, omdat het om een geleidelijk proces gaat en niet om een plotselinge gebeurtenis. Uitzondering kan zijn als de verzakking het gevolg is van een gedekte gebeurtenis, zoals een gesprongen leiding. Lees de uitsluitingen nauwkeurig. Bespreek met de klant dat hij voor funderingsherstel vaak andere routes moet zoeken, zoals gemeentelijke regelingen.`},
   {id:'vbh-037-a2',auteur:'u5',datum:'2026-02-09T15:12:00',rA:{u1:5,u8:4},rAdv:{u6:4},body:`Denk ook aan de hypotheek: bij funderingsproblemen kan de waarde van de woning dalen en kan herstel gefinancierd moeten worden. Controleer de voorwaarden van de geldverstrekker over onderhoud en waardebehoud.`},
   {id:'vbh-037-a3',auteur:'u8',datum:'2026-02-09T17:07:00',rA:{u4:4,u1:3},rAdv:{},body:`Leg vast dat je de klant hebt gewezen op de waarschijnlijke uitsluiting, zodat er geen verkeerde verwachtingen ontstaan.`}
  ]},
 {id:'vbh-038',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-11T08:25:00',views:198,tags:['grondwater','opstal','uitsluiting'],beste:null,
  titel:'Water in de kelder door hoge grondwaterstand: gedekt?',
  body:`Na een natte periode staat er water in de kelder van een klant. Er is geen leiding gesprongen. Valt dit onder de opstal of inboedel?`,
  antwoorden:[
   {id:'vbh-038-a1',auteur:'u3',datum:'2026-02-11T13:16:00',rA:{u2:4,u1:4},rAdv:{u2:4,u8:4},body:`Schade door grondwater is bij veel polissen uitgesloten of alleen gedekt als het water onvoorzien via afvoerleidingen binnenkomt. Controleer de definities van neerslag, grondwater en overstroming in de voorwaarden. De oorzaak is bepalend, dus laat de klant foto's maken en de omstandigheden vastleggen. Bij twijfel laat de verzekeraar een expert kijken.`}
  ]},
 {id:'vbh-039',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-15T09:50:00',views:166,tags:['ongedierte','opstal','uitsluiting'],beste:null,
  titel:'Muizen hebben bedrading aangevreten: schade gedekt?',
  body:`Bij een klant hebben muizen kabels in de kruipruimte doorgeknaagd, waardoor een groep in de meterkast uitvalt. Is er kans op vergoeding via de opstalverzekering?`,
  antwoorden:[
   {id:'vbh-039-a1',auteur:'u3',datum:'2026-02-15T16:06:00',rA:{u2:4,u4:4,u1:5,u5:3},rAdv:{u6:4,u4:4},body:`Schade door ongedierte en knaagdieren is meestal uitgesloten. Soms is gevolgschade gedekt, bijvoorbeeld als er daardoor brand ontstaat of een leiding gaat lekken. Controleer de uitsluitingen en de omschrijving van gevolgschade. Adviseer de klant ook om het ongedierte te laten bestrijden, want een terugkerend probleem kan later als onderhoudskwestie worden gezien.`}
  ]},
 {id:'vbh-040',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-19T18:20:00',views:105,tags:['laadpaal','opstal','elektrisch rijden'],beste:'vbh-040-a1',
  titel:'Laadpaal voor elektrische auto: verzekerd onder opstal of autopolis?',
  body:`Een klant laat een laadpaal aan de gevel van zijn woning monteren. Onder welke verzekering valt de laadpaal zelf en schade die door het laden ontstaat?`,
  antwoorden:[
   {id:'vbh-040-a1',auteur:'u3',datum:'2026-02-20T04:01:00',rA:{u7:5,u8:4,u4:5},rAdv:{u5:5,u4:5},body:`Een vast aan de woning bevestigde laadpaal valt vaak onder de opstal, omdat hij aard- en nagelvast is. Controleer of de polis maxima of voorwaarden kent voor installaties buiten de woning. Brandschade aan de woning door het laden valt doorgaans onder de opstal, schade aan de auto zelf onder de autoverzekering. Is de laadpaal geleased of eigendom van een derde, dan ligt het anders. Laat de klant de verhoging van de herbouwwaarde doorgeven als dat relevant is.`},
   {id:'vbh-040-a2',auteur:'u6',datum:'2026-02-21T02:12:00',rA:{u4:3,u7:5,u8:4},rAdv:{u7:4,u4:5,u5:3},body:`Tip voor het CRM: leg bij de woongegevens vast welke installaties er zijn, zoals laadpaal, zonnepanelen en thuisbatterij. Dan kun je bij een periodieke review gericht vragen of alles goed verzekerd is.`}
  ]},
 {id:'vbh-041',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-22T18:05:00',views:107,tags:['herbouwwaarde','duurzaamheid','opstal'],beste:null,
  titel:'Thuisbatterij en warmtepomp: moet de herbouwwaarde omhoog?',
  body:`Een klant heeft flink geïnvesteerd in verduurzaming: warmtepomp, thuisbatterij en extra isolatie. Moet de opstalverzekering worden aangepast en zijn er aandachtspunten voor de batterij?`,
  antwoorden:[]},
 {id:'vbh-042',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-26T15:45:00',views:510,tags:['VvE','appartement','opstal'],beste:'vbh-042-a1',
  titel:'Appartement: wat verzekert de VvE en wat de eigenaar zelf?',
  body:`Een klant koopt een appartement. De VvE heeft een opstalverzekering voor het gebouw. Welke verzekeringen moet de eigenaar dan nog zelf regelen?`,
  antwoorden:[
   {id:'vbh-042-a1',auteur:'u3',datum:'2026-02-26T22:50:00',rA:{u2:5},rAdv:{},body:`De VvE verzekert doorgaans het gebouw als geheel. De eigenaar regelt zelf de inboedel en vaak een aanvulling voor verbeteringen die hij zelf heeft aangebracht, zoals een nieuwe keuken of badkamer, als die niet onder de VvE-polis vallen. Vraag de polis en voorwaarden van de VvE op en kijk welke onderdelen gedekt zijn en wat het eigen risico is. Een AVP blijft ook nodig.`},
   {id:'vbh-042-a2',auteur:'u4',datum:'2026-02-27T03:15:00',rA:{u7:3,u8:4},rAdv:{},body:`Neem dit vroeg mee in het hypotheektraject. Controleer of de VvE-polis aan de eisen van de geldverstrekker voldoet en voeg een bewijs toe aan het dossier.`},
   {id:'vbh-042-a3',auteur:'u8',datum:'2026-02-27T21:41:00',rA:{u1:5},rAdv:{u4:3,u3:4},body:`Leg in het dossier vast welke dekking via de VvE loopt en welke aanvulling je hebt geadviseerd. Dat voorkomt onduidelijkheid bij een latere schade.`}
  ]},
 {id:'vbh-043',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-02T21:40:00',views:313,tags:['VvE','eigen risico','appartement'],beste:null,
  titel:'Eigen risico VvE-polis: kan de appartementseigenaar dit afdekken?',
  body:`Bij een lekkage in een appartement betaalt de eigenaar volgens het reglement het eigen risico van de VvE-polis. Is dat ergens te verzekeren?`,
  antwoorden:[
   {id:'vbh-043-a1',auteur:'u3',datum:'2026-03-03T20:42:00',rA:{u5:4},rAdv:{u6:5},body:`Sommige inboedel- of woonpolissen voor appartementseigenaren bieden een dekking voor het eigen risico van de VvE-polis, vaak tot een bepaald maximum. Controleer of dat in de huidige polis zit of als aanvulling kan. Kijk ook in het splitsingsreglement en de besluiten van de VvE wie het eigen risico draagt, dat verschilt per VvE.`}
  ]},
 {id:'vbh-044',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-06T17:40:00',views:382,tags:['hypotheek','opstal','bewijs'],beste:'vbh-044-a1',
  titel:'Geldverstrekker vraagt bewijs van opstalverzekering: wat leveren jullie aan?',
  body:`Bij de hypotheekaanvraag vraagt de geldverstrekker een bewijs dat de woning tegen brand is verzekerd. De klant heeft de polis nog niet afgesloten. Wat is jullie werkwijze?`,
  antwoorden:[
   {id:'vbh-044-a1',auteur:'u1',datum:'2026-03-07T00:24:00',rA:{u7:5,u6:5},rAdv:{u3:5,u2:4,u8:5,u7:4},body:`Ik laat de opstalverzekering ingaan per de datum van eigendomsoverdracht en vraag een voorlopig polisblad of dekkingsbevestiging op zodra de aanvraag is geaccepteerd. Controleer de voorwaarden van de geldverstrekker over wat als bewijs telt en of de geldverstrekker als belanghebbende moet worden vermeld. In het dossier sla ik het bewijs op en noteer de ingangsdatum.`},
   {id:'vbh-044-a2',auteur:'u3',datum:'2026-03-07T22:06:00',rA:{u6:3,u7:4},rAdv:{u2:4},body:`Let bij een appartement op dat de VvE-polis het bewijs is. Vraag dan een verklaring of polisblad van de VvE-beheerder op.`}
  ]},
 {id:'vbh-045',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-09T08:10:00',views:54,tags:['rieten dak','opstal','acceptatie'],beste:'vbh-045-a1',
  titel:'Rieten dak: hoe vinden jullie een passende opstalverzekering?',
  body:`Een klant koopt een woning met een rieten dak. Bij een eerste offerte is de premie fors hoger en vraagt de verzekeraar om aanvullende maatregelen. Wat zijn jullie ervaringen?`,
  antwoorden:[
   {id:'vbh-045-a1',auteur:'u3',datum:'2026-03-10T04:39:00',rA:{},rAdv:{u5:5},body:`Bij een rieten dak kijken verzekeraars naar brandpreventie: bijvoorbeeld een bevestigingsmethode die brandvertragend is, een vonkenvanger op de schoorsteen en de afstand tot andere gebouwen. Vraag na welke maatregelen invloed hebben op acceptatie en premie en laat de klant documenteren wat aanwezig is. Vergelijk meerdere aanbieders, want het beleid verschilt. Leg vast welke voorwaarden gelden, zoals keuringen.`},
   {id:'vbh-045-a2',auteur:'u5',datum:'2026-03-11T05:30:00',rA:{u3:4,u6:5,u2:3},rAdv:{u1:3,u4:4},body:`Neem de hogere premie mee in de maandlastenberekening van de hypotheek. Dat vergeten klanten nog weleens bij hun budget.`}
  ]},
 {id:'vbh-046',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-13T14:45:00',views:499,tags:['monument','herbouwwaarde','opstal'],beste:'vbh-046-a1',
  titel:'Monumentaal pand herbouwen: welke waarde verzekeren?',
  body:`Een klant woont in een rijksmonument. Bij herbouw gelden mogelijk eisen aan materialen en ambachtelijk werk. Hoe stellen jullie de herbouwwaarde vast?`,
  antwoorden:[
   {id:'vbh-046-a1',auteur:'u3',datum:'2026-03-14T05:42:00',rA:{u5:4},rAdv:{u5:5,u2:5},body:`Bij monumenten is een standaard herbouwwaardemeter vaak niet voldoende. Laat een taxatie uitvoeren door een taxateur met ervaring met monumenten, zodat de kosten van restauratie volgens de eisen worden meegenomen. Controleer of de verzekeraar herbouw naar oorspronkelijke staat dekt of herbouw naar een moderne equivalent. Leg het taxatierapport en de afspraak over de verzekerde waarde vast in het dossier.`}
  ]},
 {id:'vbh-047',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-17T20:35:00',views:126,tags:['leegstand','verkoop','opstal'],beste:null,
  titel:'Verkochte woning staat leeg tot de overdracht: risico?',
  body:`Een klant is al verhuisd naar zijn nieuwe woning; de oude woning wordt pas over een aantal maanden overgedragen. Wat moet hij regelen met de opstalverzekering?`,
  antwoorden:[
   {id:'vbh-047-a1',auteur:'u3',datum:'2026-03-18T13:41:00',rA:{u2:4,u7:4,u6:5},rAdv:{u4:4,u1:4},body:`Veel polissen beperken de dekking als een woning langer dan een bepaalde periode leegstaat, bijvoorbeeld voor diefstal, glas of waterschade. Laat de klant de leegstand melden en controleer de bepalingen. Adviseer verder: verwarming laten aanstaan of de waterleiding aftappen in de winter, regelmatig controleren en de post laten weghalen. Houd de opstal aan tot de overdracht.`},
   {id:'vbh-047-a2',auteur:'u1',datum:'2026-03-18T17:36:00',rA:{},rAdv:{u2:5,u6:5},body:`Controleer ook de afspraken in de koopovereenkomst over het risico tot de levering. Meestal blijft het risico bij de verkoper tot de overdracht.`}
  ]},
 {id:'vbh-048',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-20T17:30:00',views:403,tags:['eigen risico','premie','advies'],beste:'vbh-048-a1',
  titel:'Eigen risico verhogen om premie te besparen: wanneer adviseren jullie dat?',
  body:`Een klant wil de premie van zijn woonverzekering verlagen en vraagt of een hoger eigen risico verstandig is. Hoe onderbouwen jullie dat advies?`,
  antwoorden:[
   {id:'vbh-048-a1',auteur:'u2',datum:'2026-03-20T19:06:00',rA:{u7:5},rAdv:{u5:5},body:`Ik kijk naar de buffer van de klant. Kan hij het hogere eigen risico zonder problemen zelf betalen, dan is het vaak verstandig, omdat kleine schades dan voor eigen rekening komen. Laat de premiebesparing en het extra risico naast elkaar zien. Leg vast dat de klant bewust kiest en dat je de buffer hebt besproken.`},
   {id:'vbh-048-a2',auteur:'u3',datum:'2026-03-21T15:14:00',rA:{},rAdv:{u5:5},body:`Let erop dat het eigen risico soms per schade geldt en bij sommige dekkingen, zoals storm, apart of hoger kan zijn. Controleer dat in de voorwaarden.`}
  ]},
 {id:'vbh-049',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-24T07:50:00',views:514,tags:['pakketpolis','advies','vergelijken'],beste:'vbh-049-a1',
  titel:'Pakketpolis of losse verzekeringen: wat adviseren jullie?',
  body:`Een klant heeft bij verschillende verzekeraars losse polissen en krijgt een aanbod voor een pakketpolis met korting. Hoe beoordelen jullie of overstappen verstandig is?`,
  antwoorden:[
   {id:'vbh-049-a1',auteur:'u3',datum:'2026-03-24T17:44:00',rA:{u1:5},rAdv:{u8:3,u1:3,u5:4},body:`Vergelijk niet alleen de premie maar ook de dekkingen per onderdeel. Een pakket kan voordelig zijn, maar een onderdeel kan zwakker zijn dan de huidige losse polis. Let op opzegregels: bij een pakket kan het opzeggen van één onderdeel de korting raken. Controleer ook lopende schades en wachttijden. Leg de vergelijking vast in het dossier.`},
   {id:'vbh-049-a2',auteur:'u2',datum:'2026-03-25T13:15:00',rA:{u5:3,u3:5},rAdv:{},body:`Ik vind het gemak van één aanspreekpunt vaak een echt argument voor de klant, maar dan moet de dekking wel minimaal gelijkwaardig zijn.`}
  ]},
 {id:'vbh-050',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-28T19:10:00',views:349,tags:['premie','indexatie','klantcommunicatie'],beste:null,
  titel:'Premie woonverzekering flink gestegen zonder schade: hoe leggen jullie dat uit?',
  body:`Meerdere klanten bellen over een premieverhoging van hun woonverzekering terwijl ze geen schade hadden. Hoe leggen jullie dat uit en wat bieden jullie aan?`,
  antwoorden:[
   {id:'vbh-050-a1',auteur:'u3',datum:'2026-03-29T04:17:00',rA:{u4:4,u8:5,u6:3},rAdv:{},body:`De premie hangt vaak samen met indexatie van de herbouwwaarde en de inboedelwaarde, en met de schadelast van de verzekeraar in het algemeen. Leg uit dat indexatie juist voorkomt dat de klant onderverzekerd raakt. Bied een check aan: klopt de herbouwwaarde, is het eigen risico passend en zijn er overbodige dekkingen? Vergelijk eventueel met andere aanbieders, maar controleer dan of de dekking gelijkwaardig is.`},
   {id:'vbh-050-a2',auteur:'u6',datum:'2026-03-29T07:08:00',rA:{u2:5,u8:4,u1:5,u5:4},rAdv:{u4:4,u7:4,u8:4,u3:5},body:`Je kunt in het CRM een selectie maken van klanten met een woonpolis bij de betreffende verzekeraar en ze proactief een korte uitleg sturen. Leg de verzonden communicatie vast bij het klantdossier.`}
  ]},
 {id:'vbh-051',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-01T07:50:00',views:123,tags:['AVP','opzicht','geleende zaken'],beste:'vbh-051-a1',
  titel:'Geleende aanhanger beschadigd: dekt de AVP schade aan spullen van een ander?',
  body:`Een klant heeft een aanhanger van de buurman geleend en die beschadigd tijdens het rijden. De buurman wil dat de AVP van de klant betaalt. Is dat gedekt?`,
  antwoorden:[
   {id:'vbh-051-a1',auteur:'u3',datum:'2026-04-01T17:54:00',rA:{u8:4,u7:4},rAdv:{u5:4,u1:4,u7:5,u8:5},body:`Schade aan zaken die de verzekerde onder zich heeft, zoals geleende of gehuurde spullen, valt onder de opzichtclausule. Veel AVP-polissen sluiten dit uit of dekken het alleen beperkt, met een maximum. Daarnaast speelt hier dat schade met of door motorrijtuigen en aanhangers vaak is uitgesloten op de AVP en onder de autoverzekering valt. Controleer beide polissen. Leg vast wat je de klant hebt uitgelegd over de uitsluitingen.`},
   {id:'vbh-051-a2',auteur:'u8',datum:'2026-04-02T08:16:00',rA:{u2:5,u4:5},rAdv:{u5:5,u2:4,u3:5,u1:5},body:`Wijs de klant erop dat hij aansprakelijkheid niet zelf erkent voordat de verzekeraar heeft beoordeeld. Een erkenning kan de positie bij de verzekeraar bemoeilijken.`}
  ]},
 {id:'vbh-052',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-04T10:55:00',views:68,tags:['AVP','kinderen','aansprakelijkheid'],beste:'vbh-052-a1',
  titel:'Zoon van 15 jaar veroorzaakt schade op school: wie is aansprakelijk?',
  body:`De zoon van een klant heeft op school een dure apparatuur laten vallen. De school stelt de ouders aansprakelijk. Hoe zit het bij een kind van 15?`,
  antwoorden:[
   {id:'vbh-052-a1',auteur:'u3',datum:'2026-04-04T21:53:00',rA:{u2:4},rAdv:{u5:5,u7:5},body:`Bij kinderen vanaf 14 jaar is het kind in beginsel zelf aansprakelijk voor een eigen onrechtmatige daad; ouders zijn alleen aansprakelijk als hen zelf iets te verwijten valt. Is het kind meeverzekerd op de AVP van het gezin, dan kan de AVP de aansprakelijkheid van het kind dekken. De vraag of er sprake is van aansprakelijkheid moet wel eerst worden beoordeeld, bijvoorbeeld of het een ongeluk tijdens een les was onder toezicht. Laat de klant melden en zelf geen schuld erkennen.`},
   {id:'vbh-052-a2',auteur:'u2',datum:'2026-04-05T22:32:00',rA:{},rAdv:{u5:4},body:`Bij schade op school kan ook de verzekering van de school een rol spelen. Laat de klant navragen of de school een eigen regeling heeft.`}
  ]},
 {id:'vbh-053',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-08T21:10:00',views:5,tags:['AVP','alcohol','uitsluiting'],beste:null,
  titel:'Schade onder invloed van alcohol: kan de AVP dekking weigeren?',
  body:`Een klant heeft na een feest met alcohol op schade veroorzaakt bij een derde. Hij vreest dat de AVP niet uitkeert. Wat is jullie ervaring?`,
  antwoorden:[]},
 {id:'vbh-054',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-12T16:30:00',views:429,tags:['huurwoning','oplevering','AVP'],beste:null,
  titel:'Huurwoning bij oplevering beschadigd: valt dat onder de AVP?',
  body:`Bij het opleveren van een huurwoning brengt de verhuurder schade in rekening voor beschadigingen in vloer en deuren. De klant wil dit claimen op zijn AVP. Kan dat?`,
  antwoorden:[
   {id:'vbh-054-a1',auteur:'u3',datum:'2026-04-12T23:38:00',rA:{u2:5,u8:5,u6:3,u1:4},rAdv:{},body:`Schade aan de gehuurde woning valt vaak onder een beperkte dekking in de AVP, als die er al is. Normale slijtage en schade door geleidelijk gebruik zijn uitgesloten. Vaak geldt er een maximum en soms is alleen schade door bepaalde oorzaken gedekt, zoals water of brand. Lees de voorwaarden over huurdersaansprakelijkheid. Adviseer de klant om bij oplevering een opnamerapport te bespreken met de verhuurder.`},
   {id:'vbh-054-a2',auteur:'u4',datum:'2026-04-13T22:17:00',rA:{u8:4,u5:3,u1:4,u7:5},rAdv:{u8:4},body:`Dit is een goed punt om mee te nemen bij klanten die van een huur- naar een koopwoning gaan. Bespreek de eindoplevering ruim van tevoren.`}
  ]},
 {id:'vbh-055',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-15T10:20:00',views:101,tags:['dieren','aansprakelijkheid','paard'],beste:'vbh-055-a1',
  titel:'Klant rijdt paard van een kennis: wie is aansprakelijk bij een ongeluk?',
  body:`Een klant rijdt regelmatig op het paard van een kennis. Tijdens een rit veroorzaakt het paard schade aan een auto. Wie is aansprakelijk en welke verzekering dekt dit?`,
  antwoorden:[
   {id:'vbh-055-a1',auteur:'u3',datum:'2026-04-15T13:16:00',rA:{u5:4,u6:5,u4:4},rAdv:{u8:4,u2:5,u5:4},body:`De bezitter van een dier is in beginsel risicoaansprakelijk voor schade door het dier. De bezitter heeft daarvoor meestal een eigen aansprakelijkheidsverzekering nodig, omdat paarden op veel AVP-polissen beperkt zijn verzekerd. De berijder kan in bepaalde situaties ook aansprakelijk zijn. Controleer de AVP van de klant op dekking voor het berijden van andermans paard en de voorwaarden van de bezitter.`},
   {id:'vbh-055-a2',auteur:'u8',datum:'2026-04-15T18:24:00',rA:{u3:4,u1:5},rAdv:{u5:3,u6:5,u2:5},body:`Wijs de klant op de afspraken met de eigenaar. Vastleggen wie welk risico draagt, voorkomt discussie achteraf.`}
  ]},
 {id:'vbh-056',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-19T09:10:00',views:42,tags:['AVP','gezinsleden','uitsluiting'],beste:'vbh-056-a1',
  titel:'Schade aan spullen van een gezinslid: waarom dekt de AVP dat niet?',
  body:`Een klant heeft per ongeluk de laptop van zijn partner kapot gemaakt. De AVP keert niet uit. De klant begrijpt dat niet. Hoe leggen jullie dat uit?`,
  antwoorden:[
   {id:'vbh-056-a1',auteur:'u3',datum:'2026-04-19T13:03:00',rA:{u1:5,u8:5,u5:4},rAdv:{},body:`Een AVP dekt aansprakelijkheid tegenover derden. Gezinsleden die op dezelfde polis zijn meeverzekerd, gelden niet als derde, dus schade tussen hen is uitgesloten. Kijk of de schade onder de inboedelverzekering valt, bijvoorbeeld via een all-riskdekking. Leg de uitleg vast, zodat de klant later niet denkt dat hij verkeerd is geadviseerd.`}
  ]},
 {id:'vbh-057',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-23T09:40:00',views:155,tags:['AVP','rechtsbijstand','verweer'],beste:'vbh-057-a1',
  titel:'Aansprakelijk gesteld: AVP of rechtsbijstandsverzekering inschakelen?',
  body:`Een klant wordt aansprakelijk gesteld voor schade die hij volgens eigen zeggen niet heeft veroorzaakt. Moet hij dit bij de AVP of bij zijn rechtsbijstandsverzekering melden?`,
  antwoorden:[
   {id:'vbh-057-a1',auteur:'u3',datum:'2026-04-23T22:40:00',rA:{u5:4,u4:4},rAdv:{u2:4},body:`Meld het bij de AVP. Een AVP dekt naast eventuele schadevergoeding meestal ook het verweer tegen een onterechte aansprakelijkstelling. De rechtsbijstandsverzekering is vaak bedoeld voor situaties waarin de klant zelf schade wil verhalen; verweer tegen aansprakelijkheid is daar meestal uitgesloten. Controleer beide polissen.`},
   {id:'vbh-057-a2',auteur:'u8',datum:'2026-04-24T05:07:00',rA:{u3:5},rAdv:{u3:4,u6:4,u2:3},body:`Adviseer de klant om alle correspondentie door te sturen en niet zelf te reageren met een erkenning van aansprakelijkheid.`}
  ]},
 {id:'vbh-058',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-27T14:05:00',views:496,tags:['zzp','AVB','AVP'],beste:'vbh-058-a1',
  titel:'Zzp-klusser heeft alleen een AVP: dekt die schade bij opdrachtgevers?',
  body:`Een klant is net begonnen als zzp-klusser en heeft alleen een particuliere AVP. Bij een opdracht is schade ontstaan aan de woning van een opdrachtgever. Wat nu?`,
  antwoorden:[
   {id:'vbh-058-a1',auteur:'u3',datum:'2026-04-27T21:19:00',rA:{u8:3,u1:4},rAdv:{u4:5,u7:4},body:`Een particuliere AVP sluit aansprakelijkheid uit bedrijfs- of beroepsactiviteiten uit. Deze schade valt daarom waarschijnlijk buiten de dekking. Voor deze activiteiten is een aansprakelijkheidsverzekering voor bedrijven nodig. Bespreek met de klant het risico en adviseer zo snel mogelijk een AVB, eventueel met opzichtdekking. Leg vast dat je hem op dit gat hebt gewezen.`},
   {id:'vbh-058-a2',auteur:'u2',datum:'2026-04-28T05:28:00',rA:{u1:5},rAdv:{u5:3,u4:4},body:`Neem bij startende ondernemers standaard een verzekeringscheck op. Veel starters denken dat hun AVP voldoende is.`}
  ]},
 {id:'vbh-059',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-30T07:10:00',views:183,tags:['vriendendienst','AVP','aansprakelijkheid'],beste:null,
  titel:'Vriendendienst bij de buren loopt mis: hoe gaat de AVP hiermee om?',
  body:`Een klant hielp zijn buurman bij het ophangen van een lamp en veroorzaakte daarbij schade aan het plafond. De buurman wil vergoeding. Valt dit onder de AVP?`,
  antwoorden:[
   {id:'vbh-059-a1',auteur:'u3',datum:'2026-04-30T13:06:00',rA:{u4:5,u5:5,u8:4},rAdv:{u6:5,u2:5,u5:4},body:`Bij een vriendendienst moet eerst worden beoordeeld of de klant aansprakelijk is; bij een onbetaalde dienst wordt daar soms anders tegen aangekeken. Sommige polissen hebben een vriendendienstregeling die toch een vergoeding geeft, ook als er formeel geen aansprakelijkheid is. Controleer of de AVP van de klant zo een bepaling heeft. Meld het bij de verzekeraar en laat die beoordelen.`}
  ]},
 {id:'vbh-060',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-04T21:00:00',views:544,tags:['Kifid','klacht','schadebehandeling'],beste:'vbh-060-a1',
  titel:'Klachtprocedure: wanneer kan een klant naar het Kifid?',
  body:`Een klant is het oneens met de afwijzing van zijn schade en wil direct naar het Kifid. Welke stappen moet hij eerst doorlopen?`,
  antwoorden:[
   {id:'vbh-060-a1',auteur:'u8',datum:'2026-05-05T03:01:00',rA:{u5:3},rAdv:{u6:5,u1:4},body:`De klant moet de klacht eerst indienen bij de interne klachtenprocedure van de verzekeraar. Pas als hij een definitief standpunt heeft ontvangen of de verzekeraar niet reageert, kan hij bij het Kifid terecht. Let op de termijnen die het Kifid hanteert; controleer de actuele regels op de website van het Kifid. Als adviseur kun je de klant helpen met de onderbouwing. Leg vast welke stappen zijn gezet en wanneer.`},
   {id:'vbh-060-a2',auteur:'u3',datum:'2026-05-06T01:12:00',rA:{},rAdv:{u4:4,u5:5,u8:4},body:`Bewaar alle stukken, zoals schademelding, rapporten en correspondentie. Een overzichtelijk dossier helpt bij een eventuele procedure.`}
  ]},
 {id:'vbh-061',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-08T21:20:00',views:128,tags:['expertise','contra-expertise','schadebehandeling'],beste:null,
  titel:'Expertiserapport klopt niet volgens de klant: wat zijn de opties?',
  body:`De expert van de verzekeraar heeft de schade bij een klant veel lager ingeschat dan de offertes die de klant zelf heeft opgevraagd. Hoe gaan jullie hiermee om?`,
  antwoorden:[
   {id:'vbh-061-a1',auteur:'u3',datum:'2026-05-09T07:49:00',rA:{u1:4},rAdv:{},body:`Begin met een inhoudelijke reactie op het rapport: welke posten zijn niet meegenomen en waarom? Voeg de offertes toe. Komt de verzekeraar niet tegemoet, dan kan de klant een eigen contra-expert inschakelen. Controleer in de voorwaarden of de kosten daarvan worden vergoed en tot welk niveau. Bij blijvend verschil kunnen de experts een derde expert aanwijzen.`},
   {id:'vbh-061-a2',auteur:'u8',datum:'2026-05-09T17:31:00',rA:{u3:4,u6:5},rAdv:{u3:3,u6:4,u7:3,u4:4},body:`Leg vast welke informatie je hebt aangeleverd. Zo kun je later laten zien dat je de klant actief hebt ondersteund.`}
  ]},
 {id:'vbh-062',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-11T08:55:00',views:17,tags:['nieuwwaarde','dagwaarde','inboedel'],beste:'vbh-062-a1',
  titel:'Nieuwwaarde of dagwaarde bij inboedelschade: wanneer geldt wat?',
  body:`Een klant krijgt voor een oude televisie alleen de dagwaarde vergoed, terwijl zijn polis volgens hem nieuwwaarde dekt. Hoe zit dat?`,
  antwoorden:[
   {id:'vbh-062-a1',auteur:'u3',datum:'2026-05-12T06:09:00',rA:{u1:4,u2:5},rAdv:{u7:5,u5:4},body:`Veel inboedelpolissen vergoeden op basis van nieuwwaarde, maar maken een uitzondering voor zaken waarvan de dagwaarde onder een bepaald percentage van de nieuwwaarde ligt. Voor bepaalde categorieën, zoals elektronica of zaken die niet meer gebruikt worden, kan altijd dagwaarde gelden. Controleer de schaderegeling in de voorwaarden. Leg de klant uit hoe dat in zijn polis werkt en leg dat vast.`},
   {id:'vbh-062-a2',auteur:'u2',datum:'2026-05-13T07:01:00',rA:{u7:5,u3:4,u5:5,u6:5},rAdv:{u7:5,u5:4},body:`Bespreek dit punt ook bij een nieuwe polis. Klanten verwachten bij nieuwwaarde vaak volledige vervanging van alles.`}
  ]},
 {id:'vbh-063',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-15T07:25:00',views:166,tags:['herstel in natura','schadebehandeling','voorwaarden'],beste:'vbh-063-a1',
  titel:'Verzekeraar wil schade herstellen via eigen hersteller: moet de klant meewerken?',
  body:`De verzekeraar biedt aan om de schade te laten herstellen via een eigen netwerk van herstelbedrijven. De klant wil liever geld en zelf een aannemer kiezen. Wat zijn de rechten van de klant?`,
  antwoorden:[
   {id:'vbh-063-a1',auteur:'u3',datum:'2026-05-15T13:35:00',rA:{u2:4,u6:4},rAdv:{u4:3,u7:3},body:`Steeds meer polissen geven de verzekeraar de keuze om in natura te herstellen. Kiest de klant toch voor een eigen hersteller of geldelijke vergoeding, dan kan de vergoeding beperkt zijn tot wat het herstel via het netwerk zou kosten. Controleer de voorwaarden op deze bepaling. Bespreek met de klant wat het verschil voor hem betekent en leg zijn keuze vast.`}
  ]},
 {id:'vbh-064',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-19T10:25:00',views:72,tags:['schademelding','termijn','voorwaarden'],beste:'vbh-064-a1',
  titel:'Klant meldt schade pas maanden later: gevolgen voor dekking?',
  body:`Een klant ontdekt bij het opruimen een waterschade die waarschijnlijk al maanden geleden is ontstaan. Hij meldt het nu pas. Kan de verzekeraar weigeren?`,
  antwoorden:[
   {id:'vbh-064-a1',auteur:'u3',datum:'2026-05-19T23:23:00',rA:{u2:4,u7:4,u5:3},rAdv:{u1:5,u8:3},body:`Voorwaarden vragen meestal om een melding zo snel mogelijk. Een late melding geeft de verzekeraar niet automatisch het recht om te weigeren; dat kan in beginsel alleen als hij daardoor in een redelijk belang is geschaad, bijvoorbeeld omdat de oorzaak niet meer goed kan worden vastgesteld. Daarnaast speelt of het een geleidelijk ontstane schade is. Laat de klant direct melden en de situatie goed vastleggen.`},
   {id:'vbh-064-a2',auteur:'u8',datum:'2026-05-21T00:19:00',rA:{},rAdv:{u1:4},body:`Leg de datum van ontdekking en de datum van melding vast. Bij discussie wordt dat de basis.`}
  ]},
 {id:'vbh-065',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-23T19:30:00',views:14,tags:['mededelingsplicht','aanvraag','slotvragen'],beste:'vbh-065-a1',
  titel:'Eerdere schade niet gemeld bij aanvraag: verzekeraar beroept zich op mededelingsplicht',
  body:`Bij een schade ontdekt de verzekeraar dat de klant bij de aanvraag een eerdere opzegging niet heeft gemeld. De verzekeraar wil de dekking weigeren. Hoe kijken jullie hiernaar?`,
  antwoorden:[
   {id:'vbh-065-a1',auteur:'u8',datum:'2026-05-24T05:27:00',rA:{u4:4,u6:4,u7:3,u2:3},rAdv:{},body:`De verzekeraar moet laten zien dat de klant een vraag niet juist heeft beantwoord en dat hij bij kennis anders had beslist. De gevolgen hangen ervan af wat de verzekeraar dan zou hebben gedaan, bijvoorbeeld een hogere premie of weigering, en of er opzet tot misleiding is. Controleer het aanvraagformulier en de exacte vraagstelling. Als adviseur moet je ook kijken naar je eigen rol bij het invullen.`},
   {id:'vbh-065-a2',auteur:'u3',datum:'2026-05-25T01:25:00',rA:{u6:5},rAdv:{u5:4,u8:3,u1:5,u6:5},body:`Juist daarom loop ik de slotvragen altijd samen met de klant door en laat ik hem bevestigen dat de antwoorden kloppen. Dat staat in het dossier.`},
   {id:'vbh-065-a3',auteur:'u6',datum:'2026-05-25T20:48:00',rA:{u2:4},rAdv:{u8:5,u4:3},body:`In het adviespakket kun je de ingevulde slotvragen als bijlage opslaan bij de aanvraag. Handig voor later.`}
  ]},
 {id:'vbh-066',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-26T21:35:00',views:360,tags:['behandeltijd','schadebehandeling','klacht'],beste:null,
  titel:'Lange behandeltijd van een schade: wat kan de klant doen?',
  body:`Een schade bij een klant loopt al maanden zonder duidelijke beslissing. De klant raakt gefrustreerd. Wat doen jullie om de zaak vlot te trekken?`,
  antwoorden:[]},
 {id:'vbh-067',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-30T10:05:00',views:576,tags:['overstappen','lopende schade','woonverzekering'],beste:'vbh-067-a1',
  titel:'Overstappen naar andere verzekeraar met een lopende schade',
  body:`Een klant wil zijn woonverzekering overzetten, maar er loopt nog een schade bij de huidige verzekeraar. Kan dat zonder problemen?`,
  antwoorden:[
   {id:'vbh-067-a1',auteur:'u3',datum:'2026-05-30T16:07:00',rA:{u4:5},rAdv:{u6:4},body:`Een lopende schade blijft in principe bij de verzekeraar waar de schade is ontstaan, ook als de klant overstapt. Wel moet de klant bij de nieuwe aanvraag de lopende schade melden. Zorg dat er geen gat in de dekking ontstaat en dat de nieuwe polis direct aansluit. Bespreek of het verstandig is om te wachten tot de schade is afgehandeld, bijvoorbeeld bij herstelwerk.`},
   {id:'vbh-067-a2',auteur:'u2',datum:'2026-05-30T18:50:00',rA:{u7:4},rAdv:{},body:`Ik wacht vaak met overstappen tot het herstel klaar is. Dan voorkom je discussie over welke schade bij welke verzekeraar hoort.`}
  ]},
 {id:'vbh-068',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-03T18:45:00',views:323,tags:['samenwonen','AVP','dubbele verzekering'],beste:'vbh-068-a1',
  titel:'Samenwonen: welke polissen dubbel en welke opzeggen?',
  body:`Twee klanten gaan samenwonen en hebben allebei een AVP, inboedel en rechtsbijstand. Hoe pakken jullie de sanering aan zonder dekkingsgaten?`,
  antwoorden:[
   {id:'vbh-068-a1',auteur:'u3',datum:'2026-06-04T03:57:00',rA:{u6:5,u2:5,u5:4},rAdv:{u7:4,u5:3},body:`Maak een overzicht van alle polissen en kies per dekking de best passende. Zet de gekozen polis om naar een gezinsdekking of partnerdekking. Pas daarna zeg je de andere op, met inachtneming van de opzegtermijnen. Controleer of de inboedelwaarde van beide inboedels samen klopt. Leg vast welke polissen zijn opgezegd en welke zijn aangepast.`},
   {id:'vbh-068-a2',auteur:'u5',datum:'2026-06-05T03:10:00',rA:{},rAdv:{u6:3,u2:3,u4:4},body:`Bij een gezamenlijke hypotheek neem ik dit mee in het adviestraject, want ook de opstal moet dan op naam van beiden goed geregeld zijn.`}
  ]},
 {id:'vbh-069',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-06T15:05:00',views:320,tags:['scheiding','AVP','inboedel'],beste:'vbh-069-a1',
  titel:'Scheiding: hoe splitsen jullie de schadeverzekeringen?',
  body:`Een stel gaat uit elkaar. Een van beiden blijft in de woning. Wat moet er met de opstal, inboedel en AVP gebeuren?`,
  antwoorden:[
   {id:'vbh-069-a1',auteur:'u3',datum:'2026-06-07T10:11:00',rA:{u2:5,u7:3},rAdv:{u6:5,u5:5,u4:4},body:`Degene die vertrekt heeft vanaf het verhuismoment een eigen AVP en inboedelverzekering nodig, omdat hij of zij niet meer onder de gezinspolis valt. De achterblijvende partner past de polis aan naar alleenstaand of gezin met kinderen. De opstal volgt de eigendom; zolang beide eigenaar zijn, moet dat goed geregeld blijven. Plan dit op het moment van verhuizen en niet pas na de scheiding.`},
   {id:'vbh-069-a2',auteur:'u5',datum:'2026-06-07T15:51:00',rA:{},rAdv:{u1:3,u2:4,u3:4},body:`Koppel dit aan de afspraken in het convenant en de verdeling van de woning. Controleer de voorwaarden van de geldverstrekker rond verplichte verzekeringen.`},
   {id:'vbh-069-a3',auteur:'u8',datum:'2026-06-08T03:35:00',rA:{u1:5,u5:5,u2:5},rAdv:{},body:`Let op privacy: als beide partners klant zijn, deel je informatie over de één niet zonder toestemming met de ander.`}
  ]},
 {id:'vbh-070',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-10T13:55:00',views:541,tags:['overlijden','polis voortzetten','nabestaanden'],beste:null,
  titel:'Verzekeringnemer overleden: lopen de woonpolissen gewoon door?',
  body:`Een klant is overleden en de partner vraagt wat er met de opstal, inboedel en AVP moet gebeuren. Hoe begeleiden jullie dit?`,
  antwoorden:[
   {id:'vbh-070-a1',auteur:'u3',datum:'2026-06-10T17:48:00',rA:{u7:5},rAdv:{u4:5,u7:4,u6:3,u1:3},body:`Meestal lopen de polissen door, maar de verzekeraar moet het overlijden wel weten. De verzekeringnemer moet worden aangepast. Controleer of de nabestaande alleen achterblijft, want dan kan een AVP worden omgezet naar alleenstaand. Als de woning leeg komt te staan, gelden vaak beperkingen bij leegstand.`},
   {id:'vbh-070-a2',auteur:'u7',datum:'2026-06-11T04:28:00',rA:{u1:5},rAdv:{u1:4,u5:3},body:`Bespreek met de partner ook de overige polissen, zoals nabestaandenpensioen en overlijdensrisicoverzekering. Een volledig overzicht geeft rust.`},
   {id:'vbh-070-a3',auteur:'u8',datum:'2026-06-12T00:31:00',rA:{u7:4},rAdv:{u4:5,u2:4},body:`Wees zorgvuldig met wie je informatie deelt: vraag naar de verklaring van erfrecht of executeur als dat nodig is.`}
  ]},
 {id:'vbh-071',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-14T16:20:00',views:53,tags:['zorgplicht','herbouwwaarde','vastleggen'],beste:'vbh-071-a1',
  titel:'Klant weigert hogere herbouwwaarde: hoe leggen jullie dat vast?',
  body:`Uit een herbouwwaardeberekening blijkt dat de opstal te laag is verzekerd. De klant wil de waarde niet verhogen vanwege de premie. Hoe beschermen jullie jezelf?`,
  antwoorden:[
   {id:'vbh-071-a1',auteur:'u8',datum:'2026-06-15T07:07:00',rA:{u1:4,u7:5},rAdv:{u3:4},body:`Leg schriftelijk vast welke waarde je hebt geadviseerd, waarom, en dat de klant bewust heeft gekozen om dat niet te doen. Laat de klant dat bij voorkeur bevestigen, per e-mail of met een handtekening. Benoem in het advies de gevolgen bij schade, zoals onderverzekering. Herhaal het bij de volgende review.`},
   {id:'vbh-071-a2',auteur:'u3',datum:'2026-06-15T20:52:00',rA:{u6:3,u4:3,u7:4},rAdv:{u2:4,u6:3},body:`Ik geef het ook eenvoudig weer in getallen: wat gebeurt er bij een grote schade als de waarde te laag is? Dat maakt het voor de klant concreter.`}
  ]},
 {id:'vbh-072',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-17T21:00:00',views:217,tags:['zorgplicht','execution only','beheer'],beste:'vbh-072-a1',
  titel:'Klant sluit zelf online af en vraagt ons het beheer: welke zorgplicht hebben we?',
  body:`Een klant heeft zelf online een woonverzekering afgesloten en vraagt ons die in beheer te nemen. Welke verantwoordelijkheid hebben wij voor de inhoud van die polis?`,
  antwoorden:[
   {id:'vbh-072-a1',auteur:'u8',datum:'2026-06-18T08:00:00',rA:{},rAdv:{},body:`Als je de polis in beheer neemt, ontstaat er een relatie waarin je zorgplicht hebt voor het beheer. Leg vast of je wel of niet een advies geeft over de bestaande polis. Wil je hem alleen beheren, dan moet dat duidelijk zijn in de dienstverleningsafspraken. Een inventarisatie bij aanvang is verstandig om eventuele gaten te signaleren.`},
   {id:'vbh-072-a2',auteur:'u3',datum:'2026-06-19T01:17:00',rA:{u7:3,u6:5,u1:5,u8:4},rAdv:{u8:5},body:`Ik maak bij overname altijd een korte check van de belangrijkste punten, zoals verzekerde waarden en dekking, en stuur de klant een samenvatting.`}
  ]},
 {id:'vbh-073',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-21T16:20:00',views:449,tags:['machtiging','schadebehandeling','AVG'],beste:null,
  titel:'Schadeafwikkeling namens de klant: welke machtiging hebben jullie nodig?',
  body:`Wij behandelen schades namens klanten, maar krijgen van een verzekeraar de vraag of we gemachtigd zijn. Hoe regelen jullie dat?`,
  antwoorden:[
   {id:'vbh-073-a1',auteur:'u8',datum:'2026-06-22T14:46:00',rA:{},rAdv:{u5:4},body:`Leg in de dienstverleningsovereenkomst of opdrachtbevestiging vast dat je de klant vertegenwoordigt bij schademeldingen en -afwikkeling. Bij twijfel vraag je een aparte schriftelijke machtiging voor een specifieke schade. Verwerk alleen de gegevens die nodig zijn voor de schadebehandeling, in lijn met de AVG.`},
   {id:'vbh-073-a2',auteur:'u6',datum:'2026-06-23T12:56:00',rA:{u1:4,u2:5},rAdv:{u4:4,u5:4,u8:5,u2:4},body:`In het CRM kun je de getekende machtiging als document opslaan bij de klant en de schadezaak. Dan heb je hem direct bij de hand als een verzekeraar ernaar vraagt.`}
  ]},
 {id:'vbh-074',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-25T13:40:00',views:112,tags:['brand','herbouw','opstal'],beste:'vbh-074-a1',
  titel:'Klant wil na brand niet herbouwen: welke vergoeding?',
  body:`Na een grote brand wil een klant de woning niet herbouwen maar de grond verkopen. Hoe hoog is de vergoeding dan meestal?`,
  antwoorden:[
   {id:'vbh-074-a1',auteur:'u3',datum:'2026-06-26T02:33:00',rA:{},rAdv:{u5:5},body:`Bij een keuze om niet te herbouwen vergoeden veel polissen niet de herbouwwaarde, maar de verkoopwaarde of een andere lagere grondslag. De voorwaarden bepalen dit en soms speelt ook een termijn waarbinnen de klant moet beslissen. Laat de klant pas besluiten als duidelijk is wat de vergoeding in beide scenario's is. Leg dat overzicht in het dossier vast.`},
   {id:'vbh-074-a2',auteur:'u5',datum:'2026-06-26T04:22:00',rA:{u1:4,u3:4},rAdv:{u8:4,u7:5},body:`Betrek de geldverstrekker vroeg. De uitkering kan bestemd zijn voor aflossing en er gelden afspraken over herbouw in de hypotheekvoorwaarden.`}
  ]},
 {id:'vbh-075',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-29T13:00:00',views:228,tags:['herbouw','andere locatie','opstal'],beste:'vbh-075-a1',
  titel:'Herbouw op een andere locatie na totaal verlies: vergoedt de verzekeraar dat?',
  body:`Een klant wil na een totaal verlies van zijn woning elders een nieuwe woning bouwen of kopen. Krijgt hij dan de volle herbouwwaarde?`,
  antwoorden:[
   {id:'vbh-075-a1',auteur:'u3',datum:'2026-06-29T15:32:00',rA:{u6:4,u4:4,u8:3,u2:3},rAdv:{u2:4,u7:5},body:`Veel polissen vergoeden de herbouwwaarde als de klant binnen een bepaalde termijn herbouwt of een vervangende woning koopt, ook op een andere locatie. Soms geldt dan een maximum, bijvoorbeeld de kosten die herbouw op de oude plek zou hebben gekost. Controleer de voorwaarden en vraag de verzekeraar vooraf om bevestiging. Leg de afspraken schriftelijk vast.`}
  ]},
 {id:'vbh-076',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-02T11:25:00',views:222,tags:['huurdersbelang','inboedel','huurwoning'],beste:null,
  titel:'Huurdersbelang: moet een huurder dat apart verzekeren?',
  body:`Een klant huurt een woning en heeft zelf een nieuwe keuken en vloer laten plaatsen. Zijn die aanpassingen verzekerd?`,
  antwoorden:[]},
 {id:'vbh-077',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-06T16:00:00',views:427,tags:['glas','condens','opstal'],beste:'vbh-077-a1',
  titel:'Condens tussen dubbel glas: is dat glasschade?',
  body:`Bij een klant zitten een paar ruiten met condens tussen de glasbladen. Hij wil dit claimen op de glasverzekering. Kan dat?`,
  antwoorden:[
   {id:'vbh-077-a1',auteur:'u3',datum:'2026-07-07T04:38:00',rA:{u7:5},rAdv:{u2:4,u4:5,u6:5},body:`Condensvorming tussen dubbel glas ontstaat meestal doordat de randafdichting na verloop van tijd lek raakt. Dat is slijtage en valt bij veel glasdekkingen buiten de dekking, omdat er geen sprake is van breuk. Controleer of de polis lekslaan van isolerende beglazing expliciet dekt; sommige polissen doen dat. Adviseer de klant anders om een offerte voor vervanging te laten maken.`}
  ]},
 {id:'vbh-078',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-10T15:45:00',views:327,tags:['tuin','diefstal','inboedel'],beste:null,
  titel:'Tuinmeubelen gestolen uit de achtertuin: gedekt?',
  body:`Bij een klant zijn tuinmeubelen en een barbecue uit de achtertuin gestolen. De verzekeraar keert maar een klein deel uit. Klopt dat?`,
  antwoorden:[
   {id:'vbh-078-a1',auteur:'u3',datum:'2026-07-10T21:53:00',rA:{u7:5,u2:4,u4:4,u1:5},rAdv:{u2:4,u7:4,u1:5,u4:4},body:`Inboedel die buiten de woning maar op het eigen erf staat, zoals tuinmeubelen, valt vaak onder een aparte dekking met een lager maximum. Soms geldt dat alleen bij diefstal uit een afgesloten tuin. Controleer de voorwaarden op maxima en eisen. Als de klant veel waardevolle spullen in de tuin heeft, kan een aanvullende dekking nodig zijn.`},
   {id:'vbh-078-a2',auteur:'u2',datum:'2026-07-11T02:06:00',rA:{},rAdv:{u1:5},body:`Bij de inventarisatie vraag ik expliciet naar spullen buiten, zoals tuinmeubelen, buitenkeukens en speeltoestellen.`}
  ]},
 {id:'vbh-079',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-13T14:25:00',views:332,tags:['fiets','inboedel','maximum'],beste:'vbh-079-a1',
  titel:'Meerdere dure fietsen in huis: inboedel of aparte fietsverzekering?',
  body:`Een gezin heeft meerdere dure fietsen en een bakfiets. Wat is verstandig: alles onder de inboedel laten vallen of aparte fietsverzekeringen?`,
  antwoorden:[
   {id:'vbh-079-a1',auteur:'u3',datum:'2026-07-14T10:43:00',rA:{u1:5},rAdv:{u7:5},body:`Inboedelpolissen dekken fietsen meestal alleen thuis en vaak met een maximum per fiets of totaal. Diefstal buitenshuis is meestal niet gedekt. Voor dure fietsen en bakfietsen die veel buiten worden gebruikt, is een fietsverzekering vaak beter. Vergelijk de dekking, zoals de eisen aan sloten en registratie. Leg in het dossier vast welke keuze de klant heeft gemaakt.`},
   {id:'vbh-079-a2',auteur:'u8',datum:'2026-07-14T18:31:00',rA:{},rAdv:{u5:4},body:`Wijs de klant op de eisen voor goedgekeurde sloten. Bij diefstal is dat vaak een harde voorwaarde.`}
  ]},
 {id:'vbh-080',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-17T07:05:00',views:413,tags:['kunst','taxatie','kostbaarheden'],beste:'vbh-080-a1',
  titel:'Kunstverzameling van een klant: hoe verzekeren?',
  body:`Een klant heeft een groeiende kunstverzameling. De standaard inboedelpolis lijkt niet toereikend. Wat is jullie aanpak?`,
  antwoorden:[
   {id:'vbh-080-a1',auteur:'u3',datum:'2026-07-17T21:29:00',rA:{u7:3,u1:5,u6:5},rAdv:{},body:`Bij een waardevolle kunstverzameling adviseer ik een taxatie door een erkende taxateur en een aparte kostbaarhedenverzekering of een specifieke rubriek op de inboedel. Met een taxatierapport is de waarde vooraf vastgesteld, wat discussie bij schade voorkomt. Controleer hoe lang het rapport geldig is en of herwaardering nodig is. Ook beveiligingseisen kunnen een rol spelen.`},
   {id:'vbh-080-a2',auteur:'u2',datum:'2026-07-18T06:17:00',rA:{},rAdv:{},body:`Neem kunst ook mee in het vermogensoverzicht. Dat helpt bij planning en eventueel bij nalatenschap.`}
  ]},
 {id:'vbh-081',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-21T08:35:00',views:427,tags:['telefoon','all risk','buitenshuis'],beste:null,
  titel:'Telefoon valt kapot buitenshuis: welke dekking is nodig?',
  body:`Een klant laat zijn telefoon op straat vallen. De inboedelverzekering keert niet uit. Welke dekking had hij nodig gehad?`,
  antwoorden:[
   {id:'vbh-081-a1',auteur:'u3',datum:'2026-07-22T04:54:00',rA:{u8:5,u5:4},rAdv:{u2:4,u1:5,u8:4},body:`Een gewone inboedelverzekering dekt meestal geen val- of stootschade buitenshuis. Daarvoor is een aanvullende dekking voor mobiele apparatuur nodig, of een specifieke telefoonverzekering. Vergelijk het eigen risico en de vergoeding, die vaak beperkt is bij oudere toestellen. Bespreek met de klant of zo een dekking voor hem de moeite waard is.`}
  ]},
 {id:'vbh-082',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-25T08:40:00',views:168,tags:['all risk','uitgebreid','inboedel'],beste:'vbh-082-a1',
  titel:'All-risk of uitgebreide dekking inboedel: wat leggen jullie uit?',
  body:`Klanten vragen vaak naar het verschil tussen all-risk en uitgebreide dekking. Hoe leggen jullie het eenvoudig uit en wanneer adviseren jullie all-risk?`,
  antwoorden:[
   {id:'vbh-082-a1',auteur:'u3',datum:'2026-07-26T07:19:00',rA:{},rAdv:{u6:4},body:`Bij uitgebreide dekking zijn specifieke gebeurtenissen gedekt, zoals brand, storm, inbraak en waterschade. Bij all-risk komt daar schade door eigen onhandigheid bij, zoals vallen en stoten. Ook all-risk heeft uitsluitingen, zoals slijtage en opzet. Ik adviseer all-risk vooral bij gezinnen met kinderen of klanten met veel waardevolle spullen. Leg de keuze en de reden vast.`},
   {id:'vbh-082-a2',auteur:'u8',datum:'2026-07-26T11:09:00',rA:{u1:4},rAdv:{},body:`Voorkom dat de klant all-risk opvat als alles gedekt. Benoem de uitsluitingen expliciet.`}
  ]},
 {id:'vbh-083',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-28T14:40:00',views:143,tags:['constructiefout','gevolgschade','opstal'],beste:'vbh-083-a1',
  titel:'Constructiefout in de woning: gevolgschade wel gedekt?',
  body:`Bij een nieuwbouwwoning blijkt een constructiefout te leiden tot lekkage. Is de lekkageschade gedekt, ook al is de fout zelf uitgesloten?`,
  antwoorden:[
   {id:'vbh-083-a1',auteur:'u3',datum:'2026-07-28T21:06:00',rA:{u6:4,u7:5},rAdv:{},body:`Veel polissen sluiten de herstelkosten van het eigen gebrek uit, maar dekken wel plotselinge en onvoorziene gevolgschade, zoals waterschade aan vloeren. Lees de uitsluiting zorgvuldig: soms is gevolgschade uitgesloten als het gebrek al bekend was. Bij nieuwbouw kan er ook aanspraak zijn op de garantieregeling of de aannemer. Laat de klant beide routes onderzoeken.`},
   {id:'vbh-083-a2',auteur:'u5',datum:'2026-07-29T02:56:00',rA:{u4:3},rAdv:{u1:4,u7:4},body:`Bij nieuwbouw kijk ik altijd naar de garantie- en waarborgregeling in de koop-aannemingsovereenkomst. Dat is vaak de eerste route.`}
  ]},
 {id:'vbh-084',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-01T21:40:00',views:171,tags:['aannemer','verbouwing','aansprakelijkheid'],beste:'vbh-084-a1',
  titel:'Aannemer veroorzaakt schade tijdens verbouwing: wie betaalt?',
  body:`Tijdens een verbouwing heeft de aannemer een waterleiding geraakt, met flinke waterschade als gevolg. Moet de klant dit bij zijn opstalverzekering melden of bij de aannemer?`,
  antwoorden:[
   {id:'vbh-084-a1',auteur:'u3',datum:'2026-08-02T06:00:00',rA:{u8:5},rAdv:{u4:4},body:`De klant kan de schade bij zijn eigen opstal melden als die gedekt is. De verzekeraar kan het daarna verhalen op de aannemer. Ook kan de klant de aannemer rechtstreeks aansprakelijk stellen, die dat dan bij zijn eigen bedrijfsaansprakelijkheidsverzekering meldt. De eerste route is vaak sneller. Controleer of de verbouwing bij de verzekeraar is gemeld, want dat kan invloed hebben.`},
   {id:'vbh-084-a2',auteur:'u8',datum:'2026-08-02T10:03:00',rA:{u5:3,u1:3},rAdv:{u4:5,u7:4,u5:3,u2:3},body:`Laat de klant de schade direct fotograferen en de aannemer schriftelijk informeren. Leg vast welke stappen zijn gezet.`}
  ]},
 {id:'vbh-085',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-05T16:05:00',views:252,tags:['lekkage','appartement','VvE'],beste:null,
  titel:'Lekkage vanuit het bovengelegen appartement: wie is aanspreekpunt?',
  body:`Bij een klant lekt water vanuit het appartement erboven. De bovenburen reageren nauwelijks. Hoe regelen jullie de schade?`,
  antwoorden:[
   {id:'vbh-085-a1',auteur:'u3',datum:'2026-08-06T08:37:00',rA:{},rAdv:{u1:4,u4:3,u6:5},body:`De klant meldt de schade aan zijn inboedel bij zijn eigen inboedelverzekeraar. Schade aan het gebouw valt meestal onder de opstalpolis van de VvE. Informeer de VvE-beheerder, zodat de oorzaak kan worden onderzocht. De verzekeraars regelen onderling eventueel verhaal op de bovenburen. Laat de klant foto's maken en de datum vastleggen.`},
   {id:'vbh-085-a2',auteur:'u2',datum:'2026-08-07T05:46:00',rA:{},rAdv:{u5:3,u1:3,u7:4},body:`Vraag de klant ook of er schade is aan verbeteringen die hij zelf heeft aangebracht. Die vallen soms niet onder de VvE-polis.`}
  ]},
 {id:'vbh-086',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-08T18:10:00',views:418,tags:['riool','waterschade','opstal'],beste:null,
  titel:'Riool verstopt en water komt uit de afvoer: dekking?',
  body:`Bij een klant is het riool verstopt geraakt en is er water uit het toilet en de doucheafvoer gestroomd. Is deze schade verzekerd?`,
  antwoorden:[]},
 {id:'vbh-087',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-12T20:35:00',views:121,tags:['bliksem','overspanning','inboedel'],beste:'vbh-087-a1',
  titel:'Blikseminslag in de buurt: apparatuur kapot door overspanning',
  body:`Na een onweersbui werken bij een klant meerdere apparaten niet meer. Er is geen directe inslag op de woning geweest. Valt overspanning onder de inboedel?`,
  antwoorden:[
   {id:'vbh-087-a1',auteur:'u3',datum:'2026-08-13T14:02:00',rA:{u5:3,u4:5},rAdv:{u6:4,u5:5},body:`Veel inboedelpolissen dekken schade door overspanning of inductie als gevolg van onweer, ook als de bliksem niet direct op de woning insloeg. Vaak geldt dat alleen bij bliksem en niet bij een storing in het net. Controleer de voorwaarden en vraag een verklaring van een reparateur over de oorzaak. Bij oudere apparaten kan de vergoeding op dagwaarde zijn.`}
  ]},
 {id:'vbh-088',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-16T13:30:00',views:221,tags:['boom','storm','aansprakelijkheid'],beste:'vbh-088-a1',
  titel:'Boom van klant valt op auto van buren: aansprakelijk?',
  body:`Tijdens een storm is een boom uit de tuin van een klant op de auto van de buren gevallen. De buren stellen de klant aansprakelijk. Is dat terecht?`,
  antwoorden:[
   {id:'vbh-088-a1',auteur:'u3',datum:'2026-08-17T09:25:00',rA:{u1:3},rAdv:{u2:5,u8:3},body:`Bij storm is de klant niet automatisch aansprakelijk. Aansprakelijkheid hangt ervan af of de boom in slechte staat was en de klant dat had kunnen weten. Was de boom gezond, dan is er vaak sprake van overmacht en verhalen de buren de schade via hun eigen autoverzekering. Laat de klant het bij zijn AVP melden en niet zelf aansprakelijkheid erkennen.`},
   {id:'vbh-088-a2',auteur:'u8',datum:'2026-08-17T12:40:00',rA:{u5:4,u6:4,u2:3},rAdv:{},body:`Laat de klant foto's maken van de boom en de omstandigheden. Dat helpt bij de beoordeling.`}
  ]},
 {id:'vbh-089',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-20T07:20:00',views:148,tags:['storm','definitie','opstal'],beste:'vbh-089-a1',
  titel:'Wanneer geldt harde wind als storm in de polis?',
  body:`Een klant heeft schade aan zijn schutting door harde wind. De verzekeraar zegt dat het geen storm was. Hoe wordt dit bepaald?`,
  antwoorden:[
   {id:'vbh-089-a1',auteur:'u3',datum:'2026-08-20T18:52:00',rA:{},rAdv:{u2:5},body:`Polissen hanteren een eigen definitie van storm, meestal op basis van een minimale windsnelheid. De verzekeraar baseert zich dan op gegevens van een meetstation in de buurt. Controleer de definitie in de voorwaarden en de gemeten waarden op de schadedatum. Let ook op uitsluitingen voor schuttingen en erfafscheidingen, die vaak beperkt gedekt zijn.`}
  ]},
 {id:'vbh-090',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-23T08:35:00',views:535,tags:['doe-het-zelf','opstal','eigen schuld'],beste:'vbh-090-a1',
  titel:'Klant beschadigt zelf zijn woning bij een klus: gedekt?',
  body:`Een klant heeft bij het boren een waterleiding geraakt. Er is waterschade aan de vloer en de leiding moet worden hersteld. Valt dit onder de opstal?`,
  antwoorden:[
   {id:'vbh-090-a1',auteur:'u3',datum:'2026-08-24T05:02:00',rA:{u7:4,u6:4},rAdv:{u4:4},body:`De waterschade door een onverwacht stromend water uit een leiding is bij veel polissen gedekt, ook bij eigen schuld. De reparatie van de leiding zelf wordt soms vergoed, soms niet. Bij een all-riskopstal kan ook de directe schade door de klus gedekt zijn. Controleer de voorwaarden. Laat de klant de schade direct melden en noodmaatregelen nemen.`},
   {id:'vbh-090-a2',auteur:'u4',datum:'2026-08-24T09:51:00',rA:{u7:5},rAdv:{},body:`Dit is een mooi praktijkvoorbeeld om all-risk opstal mee te bespreken. Klanten zien het verschil dan sneller.`}
  ]},
 {id:'vbh-091',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-27T09:00:00',views:300,tags:['leegstand','buitenland','opstal'],beste:null,
  titel:'Klant verblijft maanden in het buitenland: dekking woning?',
  body:`Een klant verblijft een paar maanden per jaar in het buitenland en de woning staat dan leeg. Wat betekent dat voor de opstal- en inboedelverzekering?`,
  antwoorden:[
   {id:'vbh-091-a1',auteur:'u3',datum:'2026-08-27T16:56:00',rA:{u8:5,u5:3,u4:4},rAdv:{u1:5},body:`Controleer de leegstandsbepalingen. Bij langere afwezigheid kunnen bepaalde dekkingen vervallen. Vaak gelden er dan voorwaarden, zoals regelmatige controle door iemand en het aftappen van leidingen in de winter. Meld de afwezigheid bij de verzekeraar en vraag schriftelijk welke voorwaarden gelden.`},
   {id:'vbh-091-a2',auteur:'u8',datum:'2026-08-28T09:01:00',rA:{u2:4,u4:5},rAdv:{u2:4,u5:3},body:`Leg vast dat je de klant hebt gewezen op de leegstandsbepalingen. Bij schade komt dit vaak terug.`}
  ]},
 {id:'vbh-092',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-31T10:15:00',views:532,tags:['vakantiewoning','tweede woning','opstal'],beste:'vbh-092-a1',
  titel:'Vakantiewoning in Nederland: welke verzekering?',
  body:`Een klant heeft een tweede woning in Nederland die hij zelf gebruikt en soms verhuurt. Kan die onder dezelfde woonverzekering?`,
  antwoorden:[
   {id:'vbh-092-a1',auteur:'u3',datum:'2026-09-01T07:16:00',rA:{u7:5,u2:3},rAdv:{u5:5},body:`Een tweede woning valt meestal niet onder de woonpolis van het hoofdadres. Er is een aparte polis nodig, en bij verhuur moet dat expliciet worden gemeld. Let op leegstand en dekking voor diefstal. Sommige verzekeraars hebben een speciaal product voor recreatiewoningen.`},
   {id:'vbh-092-a2',auteur:'u2',datum:'2026-09-02T00:35:00',rA:{},rAdv:{u7:4,u6:5,u5:3,u8:3},body:`Neem de tweede woning mee in het vermogensoverzicht. Ook fiscaal heeft dat gevolgen, controleer de actuele regels.`}
  ]},
 {id:'vbh-093',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-03T14:30:00',views:440,tags:['woonboot','opstal','acceptatie'],beste:'vbh-093-a1',
  titel:'Woonboot verzekeren: waar letten jullie op?',
  body:`Een klant koopt een woonboot. Welke aandachtspunten hebben jullie bij het verzekeren daarvan?`,
  antwoorden:[
   {id:'vbh-093-a1',auteur:'u3',datum:'2026-09-04T06:20:00',rA:{u2:4},rAdv:{u1:5,u6:3},body:`Een woonboot vraagt om een specifieke verzekering. Verzekeraars vragen vaak naar het casco, de staat van de onderkant en recente inspecties. Let op dekking voor zinken, aanvaring en schade aan de ligplaats. Controleer ook de AVP-dekking voor de boot.`},
   {id:'vbh-093-a2',auteur:'u5',datum:'2026-09-05T05:09:00',rA:{u7:5,u2:5},rAdv:{u6:5},body:`Bij financiering van een woonboot gelden vaak aparte eisen. Controleer de voorwaarden van de geldverstrekker.`}
  ]},
 {id:'vbh-094',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-07T11:45:00',views:239,tags:['stacaravan','camping','verzekeren'],beste:null,
  titel:'Stacaravan op een camping: onder welke polis?',
  body:`Een klant heeft een stacaravan op een camping. Kan die onder de inboedel of moet het apart?`,
  antwoorden:[]},
 {id:'vbh-095',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-11T07:30:00',views:42,tags:['schademelding','premie','advies'],beste:'vbh-095-a1',
  titel:'Klant wil kleine schade niet melden: verstandig?',
  body:`Een klant heeft een kleine schade en twijfelt of hij die moet melden omdat hij bang is voor een hogere premie. Wat adviseren jullie?`,
  antwoorden:[
   {id:'vbh-095-a1',auteur:'u3',datum:'2026-09-11T22:26:00',rA:{u8:5,u6:5,u2:5,u1:4},rAdv:{},body:`Woonverzekeringen hebben meestal geen bonus-malussysteem zoals autoverzekeringen. Wel kan een verzekeraar bij veel schades de polis herzien of opzeggen. Bij een kleine schade onder of rond het eigen risico is melden vaak weinig zinvol. Leg uit dat het schadeverloop invloed kan hebben, maar laat de keuze bij de klant. Leg het gesprek vast.`},
   {id:'vbh-095-a2',auteur:'u8',datum:'2026-09-12T22:21:00',rA:{u7:4,u4:5,u3:4,u6:4},rAdv:{u2:4,u3:5},body:`Let op: als de klant een schade niet meldt, kan dat bij een later grotere schade vragen opleveren. Adviseer om bij twijfel toch te melden.`}
  ]},
 {id:'vbh-096',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-14T12:05:00',views:516,tags:['identiteitsfraude','cyber','verzekeren'],beste:null,
  titel:'Identiteitsfraude bij klant: valt dat ergens onder?',
  body:`Een klant is slachtoffer geworden van identiteitsfraude. Hij vraagt of zijn verzekeringen hier iets voor dekken.`,
  antwoorden:[
   {id:'vbh-096-a1',auteur:'u3',datum:'2026-09-15T10:26:00',rA:{u8:4},rAdv:{u5:5},body:`Standaard woonpolissen dekken identiteitsfraude meestal niet. Sommige verzekeraars bieden een aparte cyber- of online-dekking, of een module bij de rechtsbijstand. Controleer welke polissen de klant heeft en of er een aanvullende dekking is. Adviseer de klant ook om aangifte te doen en contact op te nemen met zijn bank.`},
   {id:'vbh-096-a2',auteur:'u8',datum:'2026-09-16T05:48:00',rA:{u7:5,u3:3},rAdv:{u3:5},body:`Bespreek hoe de klant zijn gegevens beter kan beschermen. Leg vast wat je hebt geadviseerd.`}
  ]},
 {id:'vbh-097',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-18T10:55:00',views:330,tags:['review','zorgplicht','checklist'],beste:'vbh-097-a1',
  titel:'Periodieke review schadeverzekeringen: wat staat er op jullie checklist?',
  body:`Wij willen een vaste checklist voor periodieke reviews van woonverzekeringen. Welke punten nemen jullie standaard op?`,
  antwoorden:[
   {id:'vbh-097-a1',auteur:'u3',datum:'2026-09-18T15:46:00',rA:{u6:5},rAdv:{},body:`Mijn vaste punten:
- Klopt de herbouwwaarde, zijn er verbouwingen of installaties bijgekomen?
- Is de inboedelwaarde actueel en zijn er kostbaarheden boven de maxima?
- Zijn er gezinswijzigingen, zoals samenwonen of kinderen die uit huis gaan?
- Past het eigen risico nog bij de buffer?
- Zijn er dubbele dekkingen?
Ik leg de uitkomst vast in het dossier.`},
   {id:'vbh-097-a2',auteur:'u6',datum:'2026-09-19T08:39:00',rA:{u4:3},rAdv:{u5:4,u7:4,u3:5},body:`In het CRM kun je een terugkerende taak aanmaken per klant met deze checklist. Dan wordt de review ingepland en vastgelegd.`},
   {id:'vbh-097-a3',auteur:'u8',datum:'2026-09-19T14:43:00',rA:{u1:5},rAdv:{u4:3,u2:5},body:`Leg ook vast als een klant niet reageert op een review-uitnodiging. Dat laat zien dat je je zorgplicht serieus neemt.`}
  ]},
 {id:'vbh-098',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-22T10:55:00',views:21,tags:['overstroming','opstal','uitsluiting'],beste:'vbh-098-a1',
  titel:'Woning in een overstromingsgebied: wat moet de klant weten?',
  body:`Een klant koopt een woning in een gebied waar het risico op overstroming groter is. Wat bespreken jullie over de verzekering?`,
  antwoorden:[
   {id:'vbh-098-a1',auteur:'u3',datum:'2026-09-22T23:04:00',rA:{u4:5,u8:5},rAdv:{u2:3,u8:5},body:`Overstroming door een doorbraak van primaire waterkeringen is bij veel polissen uitgesloten. Wel bieden steeds meer verzekeraars dekking voor overstroming door secundaire waterkeringen. Controleer de definities en uitsluitingen in de voorwaarden. Leg vast dat je dit hebt besproken.`},
   {id:'vbh-098-a2',auteur:'u5',datum:'2026-09-23T09:34:00',rA:{},rAdv:{u1:4},body:`Wijs de klant ook op eventuele overheidsregelingen bij rampen, maar beloof niets over vergoedingen.`}
  ]},
 {id:'vbh-099',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-26T10:15:00',views:319,tags:['AVP','logeren','kinderen'],beste:null,
  titel:'Aansprakelijkheid voor schade door een kind dat logeert',
  body:`Een logeerkind veroorzaakt schade in de woning van een klant. De ouders van het kind hebben geen AVP. Kan de klant iets?`,
  antwoorden:[
   {id:'vbh-099-a1',auteur:'u3',datum:'2026-09-26T22:37:00',rA:{u7:4,u8:3,u2:4},rAdv:{u7:4,u4:4,u5:3,u1:5},body:`Bij een kind onder de 14 jaar zijn in beginsel de ouders aansprakelijk. Zonder AVP moeten zij de schade zelf betalen. De klant kan ook kijken of zijn eigen inboedel- of opstalverzekering de schade dekt, bijvoorbeeld via all-risk. De verzekeraar kan het dan eventueel verhalen.`},
   {id:'vbh-099-a2',auteur:'u8',datum:'2026-09-27T18:46:00',rA:{u3:5,u6:3},rAdv:{u5:5,u2:4},body:`Adviseer de klant om het eerst in goed overleg met de ouders te bespreken. Leg vast wat je hebt geadviseerd.`}
  ]},
 {id:'vbh-100',cat:'verz',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-29T13:20:00',views:132,tags:['productbeëindiging','zorgplicht','klantcommunicatie'],beste:'vbh-100-a1',
  titel:'Verzekeraar stopt met een product: wat moeten wij doen?',
  body:`Een verzekeraar beëindigt een woonverzekeringsproduct en stuurt klanten een aanbod voor een nieuw product. Wat is onze rol?`,
  antwoorden:[
   {id:'vbh-100-a1',auteur:'u8',datum:'2026-09-29T21:13:00',rA:{u1:5},rAdv:{},body:`Je moet de klanten informeren en beoordelen of het nieuwe product passend is. Vergelijk de dekkingen en premie. Leg het advies per klant vast. Als de klant niet reageert, zorg dan dat hij niet onverzekerd raakt.`},
   {id:'vbh-100-a2',auteur:'u6',datum:'2026-09-30T01:32:00',rA:{u2:5,u8:5,u7:3},rAdv:{u3:5,u4:4,u7:4},body:`Je kunt in het CRM een selectie maken van alle klanten met het betreffende product en een campagne starten. Leg de verzonden berichten vast.`}
  ]},
]);
